window.TADABBUR_QAMAR = {"_meta":{"description":"تدبّر سورة القمر (٥٤)، وسورةٌ مكّيّةٌ. محورُها اقترابُ الساعةِ وانشقاقُ القمرِ آيةً، وتكذيبُ المشركين وإعراضهم، وتكرارُ قصصِ الأممِ المكذّبة (قومِ نوحٍ وعادٍ وثمودَ وقومِ لوطٍ وآلِ فرعون) مع لازمتين متكرّرتين: «فكيف كان عذابي ونذر» و«ولقد يسرنا القرآن للذكر فهل من مدكر»، وتقريرُ القدرِ وسرعةِ أمرِ الله، وجزاءِ المتّقين في مقعدِ صدق. فيها «اقتربت الساعة وانشق القمر»، و«ولقد يسرنا القرآن للذكر فهل من مدكر»، و«إنا كل شيء خلقناه بقدر»، و«في مقعد صدق عند مليك مقتدر».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":54,"name":"القمر","total_ayahs":55,"audio":[1,9,17,18,23,33,41,49,54,55],"passages":[{"title":"اقترابُ الساعةِ وإعراضُ المكذّبين، وأهوالُ البعث","range":[1,8],"theme":"اقترابُ الساعةِ وانشقاقُ القمرِ آيةً، وإعراضُ المشركين ووصفهم الآياتِ بالسحرِ واتّباعهم أهواءهم، وأنه جاءهم من الأنباءِ ما فيه مزدجرٌ وحكمةٌ بالغة، والأمرُ بالإعراضِ عنهم وتصويرُ خروجهم من القبورِ خشّعًا كالجرادِ المنتشرِ إلى الداعي يومَ العسر","verses":[{"n":1,"reflection":{"text":"«اقتربت الساعة وانشق القمر»: قربت القيامة، وانشقّ القمرُ آيةً للنبيّ؛ ففي هذا بيانُ قربِ الساعةِ ووقوعِ آيةِ انشقاقِ القمر؛ فاستعدّ للساعةِ القريبة، واعتبر بآياتِ الله الظاهرة، فالساعةُ دانيةٌ وآياتُ النبيِّ حق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للساعةِ القريبة، والاعتبارُ بآياتِ الله."},"action":{"text":"تأمّل قربَ الساعةِ وآيةَ القمر: اقتربت الساعةُ ودنت القيامة؛ وانشقّ القمرُ فرقتين آيةً معجزةً للنبيِّ ﷺ بمكّة، رآها الناسُ عيانًا «اقتربت الساعة وانشق القمر»؛ ففي هذا بيانُ قربِ الساعة، ووقوعِ معجزةِ انشقاقِ القمرِ الدالّةِ على صدقِ النبيّ؛ فقربت الساعةُ وظهرت آيةٌ من علاماتها؛ فاستعدّ أنت للساعةِ القريبةِ الدانية؛ أتى أمرُ الله فلا تستعجلوه؛ وما أمرُ الساعةِ إلا كلمحِ البصر؛ واعتبر بآياتِ الله الظاهرةِ الدالّةِ على صدقِ نبيّه؛ وانشقّ القمرُ آيةً حقًّا رآها الصحابة؛ فالساعةُ دانيةٌ قريبة، وآياتُ النبيِّ حقٌّ صادقة؛ فمن استعدّ للساعةِ واعتبر بالآياتِ نجا، ومن غفل وأعرض خسر؛ فاجعل الاستعدادَ للساعةِ والاعتبارَ بآياتِ الله دأبك."}},{"n":2,"reflection":{"text":"«وإن يروا آية يعرضوا ويقولوا سحر مستمر»، وإن يرَ المشركون آيةً يُعرِضوا ويقولوا: سحرٌ دائمٌ ذاهب؛ ففي هذا بيانُ عنادهم وإعراضهم عن الآيات؛ فاحذر الإعراضَ عن آياتِ الله ووصفَها بالسحر، فاقبل الآياتِ واعتبر بها، فالإعراضُ عن الآياتِ من العناد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ آياتِ الله والاعتبارُ بها، وتركُ الإعراضِ والعناد."},"action":{"text":"تأمّل عنادَ المشركين: وإن يرَ المشركون آيةً ومعجزةً دالّةً على صدقِ النبيِّ، كانشقاقِ القمر، يُعرِضوا عنها ولا يؤمنوا، ويقولوا: هذا سحرٌ مستمرٌّ، أي دائمٌ محكم، أو ذاهبٌ زائل «وإن يروا آية يعرضوا ويقولوا سحر مستمر»؛ ففي هذا بيانُ عنادِ المشركين وإعراضهم عن الآيات، ووصفهم إياها بالسحر؛ فلمّا رأوا انشقاقَ القمرِ أعرضوا وقالوا سحر؛ فاحذر أنت الإعراضَ عن آياتِ الله ووصفَها بالسحرِ أو الباطل؛ فاقبل الآياتِ والمعجزاتِ الدالّةَ على الحقِّ واعتبر بها؛ وإن يروا كلَّ آيةٍ لا يؤمنوا بها؛ وكأيّن من آيةٍ في السماواتِ والأرضِ يمرّون عليها وهم عنها معرضون؛ فالإعراضُ عن الآياتِ ووصفُها بالسحرِ من العنادِ والمكابرة؛ فمن قبل الآياتِ واعتبر بها اهتدى، ومن أعرض عنها ضلّ؛ فاجعل قبولَ آياتِ الله والاعتبارَ بها دأبك."}},{"n":3,"reflection":{"text":"«وكذبوا واتبعوا أهواءهم وكل أمر مستقر»، وكذّبوا بالحقِّ واتّبعوا أهواءهم، وكلُّ أمرٍ مستقرٌّ إلى غايته؛ ففي هذا بيانُ أنّ التكذيبَ سببه اتّباعُ الهوى، وأنّ كلَّ أمرٍ ينتهي إلى مستقرّه؛ فاحذر اتّباعَ الهوى الذي يجرّ للتكذيب، واعلم أنّ كلَّ عملٍ سيستقرّ إلى جزائه، فاتّبع الحقَّ لا الهوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الحقِّ لا الهوى، وإدراكُ أنّ كلَّ أمرٍ يستقرّ إلى جزائه."},"action":{"text":"تأمّل أنّ التكذيبَ من الهوى: وكذّب المشركون بالحقِّ والآيات، واتّبعوا أهواءهم ورغباتهم لا الدليل؛ وكلُّ أمرٍ من خيرٍ أو شرٍّ مستقرٌّ ومنتهٍ إلى غايته وجزائه، لا بدّ أن يظهر «وكذبوا واتبعوا أهواءهم وكل أمر مستقر»؛ ففي هذا بيانُ أنّ تكذيبَ المشركين سببه اتّباعُ الهوى، وأنّ كلَّ أمرٍ يستقرّ إلى نهايته وجزائه؛ فكذّبوا اتّباعًا للهوى؛ وكلُّ عملٍ سيستقرّ إلى جزائه؛ فاحذر أنت اتّباعَ الهوى الذي يجرّ إلى التكذيبِ وردِّ الحق؛ ومن أضلُّ ممّن اتّبع هواه بغيرِ هدًى من الله؛ ولا تتّبعِ الهوى فيضلّك؛ واعلم أنّ كلَّ عملٍ، خيرًا أو شرًّا، سيستقرّ إلى جزائه ويظهر؛ ولتعلمنّ نبأه بعد حين؛ فاتّبع الحقَّ والدليلَ لا الهوى والرغبة؛ فمن اتّبع الحقَّ نجا، ومن اتّبع الهوى كذّب وضلّ؛ فاجعل اتّباعَ الحقِّ لا الهوى دأبك."}},{"n":4,"reflection":{"text":"«ولقد جاءهم من الأنباء ما فيه مزدجر»، ولقد جاءهم من أخبارِ الأممِ المهلَكةِ ما فيه زجرٌ ورادعٌ عن الكفر؛ ففي هذا بيانُ أنّ في أخبارِ الأممِ ازدجارًا؛ فاتّعظ بأخبارِ الأممِ المهلَكة، وازدجر عن الكفرِ والمعصية، فأخبارُ الماضين رادعٌ للمعتبرين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بأخبارِ الأمم، والازدجارُ عن الكفرِ والمعصية."},"action":{"text":"تأمّل أنّ في الأنباءِ ازدجارًا: ولقد جاء هؤلاء المكذّبين من أنباءِ وأخبارِ الأممِ الماضيةِ المكذّبةِ المهلَكة، ما فيه مزدجرٌ، أي زجرٌ ورادعٌ ومانعٌ لهم عن الكفرِ والتكذيب، لو اعتبروا «ولقد جاءهم من الأنباء ما فيه مزدجر»؛ ففي هذا بيانُ أنّ في أخبارِ الأممِ المهلَكةِ التي جاءت المشركين ازدجارًا ورادعًا عن الكفر؛ لكنهم لم يزدجروا؛ فاتّعظ أنت بأخبارِ الأممِ المكذّبةِ المهلَكة؛ وازدجر بها عن الكفرِ والتكذيبِ والمعصية؛ أفلم يسيروا في الأرضِ فينظروا كيف كان عاقبةُ الذين من قبلهم؛ لقد كان في قصصهم عبرةٌ لأولي الألباب؛ فأخبارُ الماضين رادعٌ وزاجرٌ للمعتبرين المتّعظين؛ فمن اتّعظ بأخبارِ الأممِ وازدجر نجا، ومن أعرض عنها هلك؛ فاجعل الاتّعاظَ بأخبارِ الأممِ والازدجارَ عن الكفرِ والمعصيةِ دأبك."}},{"n":5,"reflection":{"text":"«حكمة بالغة فما تغن النذر»: القرآنُ حكمةٌ بالغةٌ تامّة، فما تنفع النُّذُرُ قومًا لا يؤمنون؛ ففي هذا بيانُ كمالِ حكمةِ القرآنِ وأنّ النذارةَ لا تنفع المعرضين؛ فتدبّر حكمةَ القرآنِ البالغةَ وانتفع بها، فالقرآنُ حكمةٌ تامّة، لكن لا تنفع من أعرض، فكن ممّن ينتفع بالنذارة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التدبّرُ لحكمةِ القرآنِ والانتفاعُ بالنذارة."},"action":{"text":"تأمّل كمالَ حكمةِ القرآن: هذا القرآنُ وما فيه من الأنباءِ والمواعظِ حكمةٌ بالغةٌ تامّةٌ كاملة، تبلغ غايةَ الحكمةِ في هدايةِ الخلق؛ فما تُغني ولا تنفع النُّذُرُ والرسلُ والمواعظُ قومًا لا يؤمنون ولا يعتبرون «حكمة بالغة فما تغن النذر»؛ ففي هذا بيانُ أنّ القرآنَ حكمةٌ بالغةٌ كاملة، وأنّ النذارةَ لا تنفع المعرضين المكذّبين؛ فالقرآنُ حكمةٌ تامّة، لكن لا ينتفع بها إلا من أراد الهدى؛ فتدبّر أنت حكمةَ القرآنِ البالغةَ الكاملة وانتفع بها؛ كتابٌ أُحكِمت آياته ثم فُصِّلت من لدن حكيمٍ خبير؛ ولقد ضربنا للناسِ في هذا القرآنِ من كلِّ مثل؛ وما تُغني الآياتُ والنُّذُرُ عن قومٍ لا يؤمنون؛ فالنذارةُ تنفع المؤمنين المعتبرين لا المعرضين المكذّبين؛ فكن أنت ممّن ينتفع بالنذارةِ ويتدبّر حكمةَ القرآن؛ فمن انتفع بالنذارةِ اهتدى، ومن أعرض عنها ضلّ؛ فاجعل التدبّرَ لحكمةِ القرآنِ والانتفاعَ بالنذارةِ دأبك."}},{"n":6,"reflection":{"text":"«فتول عنهم يوم يدع الداع إلى شيء نكر»: فأعرض عنهم، يا محمدُ، واذكر يومَ يدعو الداعي (إسرافيل) إلى أمرٍ فظيعٍ منكر (الحساب)؛ ففي هذا الأمرُ بالإعراضِ عن المعاندين والتذكيرِ بيومِ الدعاء؛ فأعرض عن المعاندين بعد البلاغ، واستعدّ ليومِ الدعاءِ إلى الحساب، فذلك اليومُ فظيعٌ منكر، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإعراضُ عن المعاندين بعد البلاغ، والاستعدادُ ليومِ الحساب."},"action":{"text":"تأمّل الأمرَ بالإعراضِ والتذكيرَ بيومِ الدعاء: فتولَّ وأعرض، يا محمدُ، عن هؤلاء المعاندين المكذّبين الذين لا تنفعهم النذارة؛ واذكر يومَ يدعو الداعي (إسرافيلُ بالنفخِ في الصور) الخلائقَ إلى شيءٍ نُكُرٍ، أي أمرٍ فظيعٍ منكرٍ تنكره النفوس، وهو الحسابُ والموقفُ العظيم «فتول عنهم يوم يدع الداع إلى شيء نكر»؛ ففي هذا الأمرُ للنبيِّ بالإعراضِ عن المعاندين، والتذكيرِ بيومِ يدعو فيه الداعي إلى الحسابِ الفظيع؛ فأعرض أنت عن المعاندين المصرّين بعد أن بلّغتهم؛ واستعدّ ليومِ الدعاءِ إلى الحسابِ والموقفِ العظيم؛ يومَ يدعوكم فتستجيبون بحمده؛ يومَ يدعُ الداعِ إلى شيءٍ نُكُر؛ فذلك اليومُ فظيعٌ منكرٌ تنكره النفوس؛ فاعمل أنت لذلك اليومِ بالإيمانِ والعملِ الصالح؛ فمن استعدّ ليومِ الحسابِ نجا، ومن غفل عنه خسر؛ فاجعل الإعراضَ عن المعاندين والاستعدادَ ليومِ الحسابِ دأبك."}},{"n":7,"reflection":{"text":"«خشعا أبصارهم يخرجون من الأجداث كأنهم جراد منتشر»: خاشعةً ذليلةً أبصارهم، يخرجون من القبورِ كأنهم جرادٌ منتشرٌ في الكثرةِ والانتشار؛ ففي هذا بيانُ حالِ الناسِ يومَ البعث؛ فاستعدّ ليومِ البعثِ الذي تخرج فيه من قبرك ذليلًا، فأهوالُ البعثِ عظيمة، فاعمل لذلك اليوم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ البعث، والعملُ له قبل أهواله."},"action":{"text":"تأمّل حالَ الناسِ يومَ البعث: يخرج الناسُ يومَ القيامةِ من قبورهم خاشعةً ذليلةً خاضعةً أبصارهم من الهولِ والفزع؛ يخرجون من الأجداثِ (القبور) مسرعين، كأنهم في كثرتهم وانتشارهم وحيرتهم جرادٌ منتشرٌ متفرّقٌ يموج بعضه في بعض «خشعا أبصارهم يخرجون من الأجداث كأنهم جراد منتشر»؛ ففي هذا بيانُ حالِ الناسِ يومَ البعث: خاشعةً أبصارهم، يخرجون من القبورِ كالجرادِ المنتشر؛ فيخرجون أذلّةً حائرين مسرعين؛ فاستعدّ أنت ليومِ البعثِ الذي تخرج فيه من قبرك ذليلًا خاشعًا؛ يومَ يخرجون من الأجداثِ سراعًا كأنهم إلى نُصُبٍ يوفضون، خاشعةً أبصارهم؛ فأهوالُ البعثِ عظيمةٌ مفزعة؛ فاعمل أنت لذلك اليومِ العظيمِ بالإيمانِ والعملِ الصالحِ قبل مجيئه؛ فمن استعدّ ليومِ البعثِ نجا، ومن غفل عنه خسر؛ فاجعل الاستعدادَ ليومِ البعثِ والعملَ له دأبك."}},{"n":8,"reflection":{"text":"«مهطعين إلى الداع يقول الكافرون هذا يوم عسر»: مسرعين مادّي أعناقهم إلى الداعي، يقول الكافرون: هذا يومٌ صعبٌ شديد؛ ففي هذا بيانُ شدّةِ يومِ القيامةِ على الكافرين؛ فاعمل ليومِ القيامةِ لييسُر عليك، فهو عسيرٌ على الكافرين يسيرٌ على المؤمنين، فاستعدّ له بالإيمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ ليومِ القيامةِ لييسُر، وإدراكُ عسرِه على الكافرين."},"action":{"text":"تأمّل شدّةَ يومِ القيامة: يخرج الناسُ مهطعين، أي مسرعين مادّي أعناقهم، مقبلين، إلى الداعي الذي يدعوهم إلى المحشر، لا يلوون على شيء؛ يقول الكافرون في ذلك اليوم: هذا يومٌ عسِرٌ صعبٌ شديدٌ علينا «مهطعين إلى الداع يقول الكافرون هذا يوم عسر»؛ ففي هذا بيانُ إسراعِ الناسِ إلى الداعي، وشدّةِ ذلك اليومِ على الكافرين حيث يصفونه بالعسر؛ فهو يومٌ عسيرٌ على الكافرين؛ فكان يومًا على الكافرين عسيرًا، غيرَ يسير؛ فاعمل أنت ليومِ القيامةِ بالإيمانِ والعملِ الصالحِ لييسُر عليك؛ فذلك اليومُ عسيرٌ على الكافرين، يسيرٌ على المؤمنين المتّقين؛ فأمّا من أوتي كتابه بيمينه فسوف يُحاسَب حسابًا يسيرًا؛ فاستعدّ له بالإيمانِ والتقوى والعملِ الصالح؛ فمن آمن وعمل صالحًا يسُر عليه، ومن كفر عسُر عليه؛ فاجعل العملَ ليومِ القيامةِ بالإيمانِ لييسُر عليك دأبك."}}]},{"title":"قصةُ نوحٍ وإهلاكُ قومه بالطوفان","range":[9,17],"theme":"تكذيبُ قومِ نوحٍ لعبدِ الله ورميهم إياه بالجنون، ودعاؤه ربَّه أني مغلوبٌ فانتصر، وفتحُ أبوابِ السماءِ بماءٍ منهمرٍ وتفجيرِ الأرضِ عيونًا، وحملُه على السفينةِ تجري بأعينِ الله جزاءً له، وتركُها آيةً، ولازمتا «فكيف كان عذابي ونذر» و«ولقد يسرنا القرآن للذكر فهل من مدكر»","verses":[{"n":9,"reflection":{"text":"«كذبت قبلهم قوم نوح فكذبوا عبدنا وقالوا مجنون وازدجر»: كذّبت قبلهم قومُ نوحٍ فكذّبوا عبدَنا نوحًا وقالوا: مجنون، وزُجِر وأُوذي؛ ففي هذا بدءُ قصصِ الأممِ بتكذيبِ قومِ نوح؛ فاعتبر بتكذيبِ قومِ نوحٍ لنبيّهم وأذاهم له، فتكذيبُ الرسلِ وأذاهم سنّةُ المكذّبين، فلا يحزنك تكذيبُ المعرضين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بتكذيبِ الأمم، والصبرُ على أذى المكذّبين."},"action":{"text":"تأمّل بدءَ قصصِ الأمم: كذّبت قبل هؤلاء المشركين قومُ نوحٍ رسولهم؛ فكذّبوا عبدَنا نوحًا عليه السلام؛ وقالوا فيه: مجنونٌ زائلُ العقل؛ وازدُجِر، أي زُجِر ونُهِر وأُوذي وهُدِّد ليكفّ عن الدعوة «كذبت قبلهم قوم نوح فكذبوا عبدنا وقالوا مجنون وازدجر»؛ ففي هذا بدءُ قصصِ الأممِ المكذّبةِ بتكذيبِ قومِ نوحٍ لنبيّهم، ورميهم إياه بالجنون، وأذاهم له؛ فكذّبوه وآذوه ورموه بالجنون؛ ولاحظ وصفَ نوحٍ بالعبوديةِ (عبدنا) تشريفًا؛ فاعتبر أنت بتكذيبِ قومِ نوحٍ لنبيّهم وأذاهم له؛ فتكذيبُ الرسلِ ورميهم بالجنونِ وأذاهم سنّةُ المكذّبين في كلِّ زمان؛ ولقد كُذِّبت رسلٌ من قبلك؛ كذلك ما أتى الذين من قبلهم من رسولٍ إلا قالوا ساحرٌ أو مجنون؛ فلا يحزنك أنت تكذيبُ المعرضين وأذاهم في سبيلِ الحق؛ فمن صبر على أذى المكذّبين نُصِر، ومن جزع خسر؛ فاجعل الاعتبارَ بتكذيبِ الأممِ والصبرَ على أذى المكذّبين دأبك."}},{"n":10,"reflection":{"text":"«فدعا ربه أني مغلوب فانتصر»: فدعا نوحٌ ربه: أني مغلوبٌ فانتصر لي؛ ففي هذا بيانُ لجوءِ نوحٍ إلى الله بعد بذلِ الدعوة؛ فالجأ إلى الله بالدعاءِ بعد بذلِ جهدك، فإذا عجزت عن نصرِ نفسك فوّض أمرك إلى الله، فالدعاءُ سلاحُ المؤمن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله بالدعاءِ بعد بذلِ الجهد."},"action":{"text":"تأمّل لجوءَ نوحٍ إلى الله: فلمّا يئس نوحٌ من إيمانِ قومه بعد طولِ الدعوةِ (٩٥٠ سنة) وأذاهم له، دعا ربه: أني مغلوبٌ مقهورٌ من قومي، عاجزٌ عن نصرِ نفسي، فانتصر لي منهم بإهلاكهم «فدعا ربه أني مغلوب فانتصر»؛ ففي هذا بيانُ لجوءِ نوحٍ إلى الله بالدعاءِ بعد بذلِ الدعوةِ والصبرِ الطويل؛ فلمّا عجز عن نصرِ نفسه فوّض أمره إلى الله؛ فالجأ أنت إلى الله بالدعاءِ بعد بذلِ جهدك في الحقِّ والدعوة؛ فإذا عجزت عن نصرِ نفسك أو دفعِ الظلمِ فوّض أمرك إلى الله وادعه؛ ربِّ إني مغلوبٌ فانتصر؛ فدعا ربه أنّ هؤلاء قومٌ مجرمون؛ وأيّوب إذ نادى ربه أني مسّني الضرّ؛ فالدعاءُ سلاحُ المؤمنِ بعد بذلِ الأسباب؛ فمن بذل الجهدَ ثم لجأ إلى الله بالدعاءِ كفاه الله، ومن اعتمد على نفسه خُذِل؛ فاجعل اللجوءَ إلى الله بالدعاءِ بعد بذلِ الجهدِ دأبك."}},{"n":11,"reflection":{"text":"«ففتحنا أبواب السماء بماء منهمر»: ففتحنا أبوابَ السماءِ بماءٍ كثيرٍ منصبٍّ متتابع؛ ففي هذا بيانُ إجابةِ الله لدعاءِ نوح؛ فاعلم أنّ الله يجيب دعاءَ المظلومِ الملتجئِ إليه، فادعُ الله واثقًا بالإجابة، فإجابةُ الدعاءِ من نصرِ الله لأوليائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بإجابةِ الله للدعاء، وإدراكُ نصرِه لأوليائه."},"action":{"text":"تأمّل إجابةَ الله لدعاءِ نوح: فاستجاب الله دعاءَ نوح؛ ففتحنا أبوابَ السماءِ بماءٍ منهمرٍ، أي كثيرٍ متتابعٍ منصبٍّ بغزارة؛ فنزل المطرُ بغزارةٍ عظيمةٍ لم يُعهَد مثلها «ففتحنا أبواب السماء بماء منهمر»؛ ففي هذا بيانُ إجابةِ الله لدعاءِ نوحٍ بإرسالِ الماءِ الغزيرِ للطوفان؛ فأجاب دعاءه ونصره؛ فاعلم أنت أنّ الله يجيب دعاءَ المظلومِ الملتجئِ إليه، وينصر أولياءه؛ ادعوني أستجب لكم؛ أمّن يجيب المضطرَّ إذا دعاه ويكشف السوء؛ وكان حقًّا علينا نصرُ المؤمنين؛ فادعُ أنت الله واثقًا بإجابته لك؛ فإجابةُ الدعاءِ من نصرِ الله لأوليائه المظلومين؛ فمن دعا الله بصدقٍ وثقة أجابه ونصره؛ فاجعل الثقةَ بإجابةِ الله للدعاءِ ونصرِه لأوليائه دأبك."}},{"n":12,"reflection":{"text":"«وفجرنا الأرض عيونا فالتقى الماء على أمر قد قدر»، وفجّرنا الأرضَ عيونًا، فالتقى ماءُ السماءِ والأرضِ على أمرٍ قد قدّره الله؛ ففي هذا بيانُ تدبيرِ الله لإهلاكِ قومِ نوح؛ فاعلم أنّ ما يقع بقدرِ الله وتدبيره، فسلّم لقدرِ الله، فكلُّ شيءٍ يجري بأمرٍ مقدّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لقدرِ الله، وإدراكُ أنّ كلَّ شيءٍ بأمرٍ مقدّر."},"action":{"text":"تأمّل تدبيرَ الله للطوفان: وفجّرنا الأرضَ كلَّها عيونًا متدفّقةً بالماء؛ فالتقى ماءُ السماءِ النازلُ وماءُ الأرضِ النابعُ على أمرٍ قد قدّره الله وقضاه من إهلاكِ قومِ نوح؛ فاجتمع الماءان بتقديرٍ إلهيٍّ محكم «وفجرنا الأرض عيونا فالتقى الماء على أمر قد قدر»؛ ففي هذا بيانُ تدبيرِ الله العجيبِ لإهلاكِ قومِ نوحٍ بالطوفان، بالتقاءِ ماءِ السماءِ والأرضِ على أمرٍ مقدّر؛ فكان الإهلاكُ بقدرٍ محكم؛ فاعلم أنت أنّ ما يقع في الكونِ يجري بقدرِ الله وتدبيره وأمره؛ إنّا كلَّ شيءٍ خلقناه بقدر؛ وكان أمرُ الله قدرًا مقدورًا؛ فسلّم لقدرِ الله وتدبيره في كلِّ ما يقع؛ فكلُّ شيءٍ يجري بأمرٍ مقدّرٍ من الله بحكمته؛ فمن سلّم لقدرِ الله اطمأنّ، ومن اعترض تعب؛ فاجعل التسليمَ لقدرِ الله وإدراكَ أنّ كلَّ شيءٍ بأمرٍ مقدّرٍ دأبك."}},{"n":13,"reflection":{"text":"«وحملناه على ذات ألواح ودسر»، وحملنا نوحًا على سفينةٍ ذاتِ ألواحٍ ومساميرَ؛ ففي هذا بيانُ نجاةِ نوحٍ بالسفينة؛ فاعلم أنّ الله ينجّي أولياءه بالأسبابِ التي يهيّئها، فخذ بالأسبابِ متوكّلًا على الله، فالنجاةُ بتدبيرِ الله وأسبابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأخذُ بالأسبابِ مع التوكّل، وإدراكُ أنّ النجاةَ بتدبيرِ الله."},"action":{"text":"تأمّل نجاةَ نوحٍ بالسفينة: وحملنا نوحًا ومن آمن معه على سفينةٍ ذاتِ ألواحٍ (أخشابٍ عريضة) ودُسُرٍ (مساميرَ تشدّها، أو حبال)؛ فنجّاهم بها من الطوفان «وحملناه على ذات ألواح ودسر»؛ ففي هذا بيانُ نجاةِ نوحٍ ومن معه بالسفينةِ التي صنعها بأمرِ الله؛ فنجّاهم الله بهذا السببِ الذي هيّأه؛ فاعلم أنت أنّ الله ينجّي أولياءه بالأسبابِ التي يهيّئها ويأمر بها؛ واصنعِ الفلكَ بأعيننا ووحينا؛ فأنجيناه وأصحابَ السفينة؛ فخذ أنت بالأسبابِ المشروعةِ متوكّلًا على الله؛ فالأخذُ بالأسبابِ مع التوكّلِ من سنّةِ الأنبياء؛ اعقلها وتوكّل؛ فالنجاةُ بتدبيرِ الله وأسبابه التي يهيّئها؛ فمن أخذ بالأسبابِ وتوكّل على الله نجا، ومن أهملها أو اعتمد عليها وحدها خسر؛ فاجعل الأخذَ بالأسبابِ مع التوكّلِ على الله دأبك."}},{"n":14,"reflection":{"text":"«تجري بأعيننا جزاء لمن كان كفر»: تجري السفينةُ بحفظِنا ورعايتنا، جزاءً لنوحٍ الذي كُفِر (كُذِّب)؛ ففي هذا بيانُ حفظِ الله لنوحٍ وانتصارِه له؛ فاعلم أنّ الله يحفظ أولياءه وينتصر لهم، فاطمئن لحفظِ الله ونصره، فمن كان الله حافظه فلا يضرّه أحد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ لحفظِ الله ونصرِه لأوليائه."},"action":{"text":"تأمّل حفظَ الله لنوح: تجري السفينةُ بأعيننا، أي بمرأًى منّا وحفظٍ ورعايةٍ وكلاءة؛ جزاءً ونصرةً لنوحٍ الذي كان كُفِر، أي كُذِّب وجُحِدت نعمةُ الله على يديه، فانتصر الله له بإهلاكِ قومه ونجاته «تجري بأعيننا جزاء لمن كان كفر»؛ ففي هذا بيانُ حفظِ الله لنوحٍ ورعايتِه لسفينته، وانتصارِه له ممّن كذّبه؛ فحفظه الله ونصره؛ فاعلم أنت أنّ الله يحفظ أولياءه بعينه ورعايته، وينتصر لهم ممّن ظلمهم وكذّبهم؛ ولتُصنَع على عيني؛ واصبر لحكمِ ربّك فإنك بأعيننا؛ إنا لننصر رسلنا والذين آمنوا؛ فاطمئن أنت لحفظِ الله ونصرِه لأوليائه؛ فمن كان الله حافظه ووليّه فلا يضرّه من كذّبه أو ظلمه؛ فمن اطمأنّ لحفظِ الله ونصره صبر وثبت، ومن جزع خسر؛ فاجعل الطمأنينةَ لحفظِ الله ونصرِه لأوليائه دأبك."}},{"n":15,"reflection":{"text":"«ولقد تركناها آية فهل من مدكر»، ولقد تركنا قصةَ نوحٍ (أو السفينةَ) آيةً وعبرة، فهل من متّعظٍ معتبر؟ ففي هذا الحثُّ على الاتّعاظ؛ فاتّعظ بقصةِ نوحٍ وكن من المدّكرين المعتبرين، فالله يترك الآياتِ للعبرة، فكن ممّن يتذكّر بها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بقصصِ الأمم، وكونُ العبدِ من المدّكرين."},"action":{"text":"تأمّل الحثَّ على الاتّعاظ: ولقد تركنا هذه القصةَ (قصةَ نوحٍ والطوفانِ والسفينة) آيةً وعبرةً وعظةً باقية؛ فهل من مدّكرٍ، أي متّعظٍ معتبرٍ متذكّرٍ يتّعظ بها؟ «ولقد تركناها آية فهل من مدكر»؛ ففي هذا الحثُّ على الاتّعاظِ بقصةِ نوحٍ، والاستفهامُ عمّن يتذكّر ويعتبر؛ فترك الله القصةَ آيةً للعبرة؛ فاتّعظ أنت بقصةِ نوحٍ وقومه، وكن من المدّكرين المعتبرين المتّعظين؛ فهذه القصصُ تركها الله آياتٍ للعبرةِ والاتّعاظ؛ لقد كان في قصصهم عبرةٌ لأولي الألباب؛ إنّ في ذلك لآيةً وما كان أكثرهم مؤمنين؛ فكن أنت ممّن يتذكّر ويعتبر بآياتِ الله وقصصه؛ (وتتكرّر هذه اللازمةُ في السورةِ تأكيدًا للاتّعاظ)؛ فمن اتّعظ بقصصِ الأممِ واعتبر نجا، ومن أعرض عنها هلك؛ فاجعل الاتّعاظَ بقصصِ الأممِ وكونَك من المدّكرين دأبك."}},{"n":16,"reflection":{"text":"«فكيف كان عذابي ونذر»: فكيف كان عذابي لهم وإنذاري؟ ففي هذا التهويلُ لعذابِ الله وتذكيرٌ بنذارته؛ فتأمّل شدّةَ عذابِ الله للمكذّبين واتّعظ بنذارته، فعذابُ الله شديد، ونذارتُه حق، فاحذر أن يصيبك ما أصابهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بشدّةِ عذابِ الله ونذارته، والحذرُ منها."},"action":{"text":"تأمّل التهويلَ لعذابِ الله: فكيف كان عذابي لقومِ نوحٍ المكذّبين، ونُذُري، أي إنذاري لهم قبل العذاب؟ استفهامٌ للتهويلِ والتعظيمِ لشأنِ العذابِ والإنذار «فكيف كان عذابي ونذر»؛ ففي هذا التهويلُ لعذابِ الله الذي أصاب المكذّبين، والتذكيرُ بأنه سبق بالنذارةِ والإنذار؛ فكان عذابه شديدًا بعد إنذارٍ بالغ؛ فتأمّل أنت شدّةَ عذابِ الله للمكذّبين، وأنه أنذرهم قبله فلم يتّعظوا؛ فعذابُ الله شديدٌ لمن استحقّه؛ إنّ بطشَ ربّك لشديد؛ وكذلك أخذُ ربّك إذا أخذ القرى وهي ظالمةٌ إنّ أخذه أليمٌ شديد؛ ونذارةُ الله حقٌّ سبقت العذاب؛ وما كنّا معذّبين حتى نبعث رسولًا؛ (وتتكرّر هذه اللازمةُ تهويلًا)؛ فاحذر أنت أن يصيبك ما أصاب المكذّبين، واتّعظ بالنذارةِ قبل العذاب؛ فمن اتّعظ بالنذارةِ نجا، ومن أعرض عنها ذاق العذاب؛ فاجعل الاتّعاظَ بشدّةِ عذابِ الله ونذارته والحذرَ منها دأبك."}},{"n":17,"reflection":{"text":"«ولقد يسرنا القرآن للذكر فهل من مدكر»، ولقد سهّلنا القرآنَ للحفظِ والفهمِ والاتّعاظ، فهل من متّعظٍ معتبر؟ ففي هذا بيانُ تيسيرِ القرآنِ للذكرِ والحثُّ على التذكّر به؛ فاعلم أنّ القرآنَ ميسَّرٌ للحفظِ والفهمِ والعمل، فأقبل عليه متذكّرًا، وكن من المدّكرين، فالقرآنُ ميسَّرٌ لمن أراد الذكرى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على القرآنِ المُيسَّرِ متذكّرًا، وكونُ العبدِ من المدّكرين."},"action":{"text":"تأمّل تيسيرَ القرآنِ للذكر: ولقد يسّرنا وسهّلنا القرآنَ للذكرِ، أي للحفظِ والتلاوةِ والفهمِ والتدبّرِ والاتّعاظِ والعمل؛ فهل من مدّكرٍ متّعظٍ يتذكّر به ويعمل بمقتضاه؟ «ولقد يسرنا القرآن للذكر فهل من مدكر»؛ ففي هذا بيانُ أنّ الله يسّر القرآنَ للحفظِ والفهمِ والاتّعاظ، والحثُّ على التذكّرِ به والعملِ بمقتضاه؛ (وتتكرّر هذه اللازمةُ أربعَ مرّاتٍ في السورةِ تأكيدًا وحثًّا)؛ فالقرآنُ ميسَّرٌ لمن أراد الذكرى؛ فاعلم أنت أنّ القرآنَ ميسَّرٌ للحفظِ والتلاوةِ والفهمِ والتدبّرِ والعمل؛ فأقبل عليه متذكّرًا متّعظًا عاملًا بمقتضاه؛ فإنما يسّرناه بلسانك لعلّهم يتذكّرون؛ كتابٌ أنزلناه إليك مباركٌ ليدّبّروا آياته؛ وكن من المدّكرين المتّعظين بالقرآن؛ فالقرآنُ ميسَّرٌ للذكرى والاتّعاظِ لمن أراده؛ فمن أقبل على القرآنِ متذكّرًا اهتدى، ومن أعرض عنه ضلّ؛ فاجعل الإقبالَ على القرآنِ المُيسَّرِ متذكّرًا وكونَك من المدّكرين دأبك."},"qadiyya":{"title":"قضيّةُ التيسير: أيّ شيءٍ يُسّر من القرآن، ولمن؟","question":"تكرّر في سورة القمر أربعَ مرّات: «ولقد يسّرنا القرآنَ للذكر فهل من مدّكر».\nوالتكرارُ في موضعٍ واحدٍ أربعَ مرّاتٍ لافت.\nفالقضيّة: ما الذي يُسّر منه؟ **ألفظُه أم معناه**؟ ثمّ: ما «الذكر» الذي يُسّر له؟ ثمّ: **هل التيسير عامٌّ لكلّ أحد أم مشروط**؟","background":"ولا يُفهم مقدارُ الوعد حتى نعرف أنّ للكتاب جهتين يُطلبان:\nجهةُ اللفظ: أن يُحفظ ويُتلى.\nوجهةُ المعنى: أن يُفهم ويُعلم.\n**وقد تُيسَّر إحداهما دون الأخرى**؛ فمن الكتب ما يسهل حفظُه ويعسر فهمُه، ومنها عكسُه.\nوالدعوى في الآية **أنّهما يُسّرتا معًا**.\nوهذه دعوى تُختبر، لا تُقال ثمّ تُترك.","what_happened":"فسّر السعديُّ التيسير **بالجهتين معًا**: «أي: ولقد يسّرنا وسهّلنا هذا القرآن الكريم، ألفاظَه للحفظ والأداء، ومعانيَه للفهم والعلم».\n⭐ ثمّ علّل ذلك بثلاثة أوصافٍ في الكتاب نفسِه: «لأنّه أحسنُ الكلام لفظًا، وأصدقُه معنًى، وأبينُه تفسيرًا».\n**فردّ التيسير إلى صفةٍ في المُيسَّر**، لا إلى مجرّد وعدٍ مجرّد.\n⭐ ثمّ قرّر **أنّ التيسير يقع بحسب الإقبال**: «فكلُّ من أقبل عليه يسّر اللهُ عليه مطلوبَه غايةَ التيسير، وسهّله عليه».\n⭐ ثمّ وسّع معنى «الذكر»: «والذكرُ شاملٌ لكلّ ما يتذكّر به العاملون، من الحلال والحرام، وأحكامِ الأمر والنهي، وأحكامِ الجزاء والمواعظِ والعبر، والعقائدِ النافعة والأخبارِ الصادقة».\n⭐ ثمّ رتّب على ذلك **حكمًا في مراتب العلوم**: «ولهذا كان علمُ القرآن حفظًا وتفسيرًا أسهلَ العلوم، وأجلَّها على الإطلاق».\nثمّ ذكر ما يخصّه: «وهو العلم النافع الذي إذا طلبه العبدُ أُعين عليه».\n⭐ ثمّ نقل عن بعض السلف عند هذه الآية: «هل من طالب علمٍ فيُعان؟».","the_verdict":"فالحاصلُ أنّ الآية **دعوى مقرونةٌ بسببها وبشرطها**.\n⭐ فأمّا السببُ فصفةُ الكتاب: «أحسنُ الكلام لفظًا، وأصدقُه معنًى، وأبينُه تفسيرًا».\nوأمّا الشرطُ فالإقبال: «فكلُّ من أقبل عليه يسّر اللهُ عليه مطلوبَه».\nفالتيسيرُ ليس أن يدخل العلمُ بلا طلب؛ **إنّه أن يُعان الطالبُ إذا طلب**.\nولهذا كان الاعتراضُ بأنّ الفهم صعبٌ غيرَ وارد على الآية؛ **فإنّ الوعد معلّقٌ بالإقبال**، والذي لم يُقبل لم يدخل في شرطه.\n⭐ وأمّا قولُه إنّ علم القرآن «أسهلُ العلوم وأجلُّها على الإطلاق» فجمعٌ بين وصفين لا يجتمعان عادةً.\nفإنّ الأصل أنّ أجلَّ العلوم أصعبُها؛ إذ الشرفُ يُنال بالكلفة.\nفلمّا اجتمع في هذا العلم الجلالةُ والسهولة كان ذلك من خصائصه.\nوالذي يُفوّته إنّما يُفوّته **لأنّه ظنّه عسيرًا، لا لأنّه جرّبه فأعياه**.\n⭐ وأمّا نقلُه عن بعض السلف فسؤالٌ في صورة عرض: «هل من طالب علمٍ فيُعان؟».\nفجُعلت العونُ مضمونةً والطلبُ مطلوبًا.\nفالبابُ مفتوح، والنقصُ في الداخل لا في الباب.\n⭐ وأمّا سعةُ «الذكر» عنده فترفع تصوّرًا ضيّقًا: أن يُظنّ التذكّرُ وعظًا يُرقّق القلب فحسب.\nوقد عدّ فيه: الحلالَ والحرام، وأحكامَ الأمر والنهي، وأحكامَ الجزاء، والمواعظَ والعبر، والعقائدَ، والأخبار.\nفالتيسيرُ إذًا في هذه الأبواب كلِّها، **لا في باب الوعظ وحده**.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: **لا تُصدّق نفسك** إذا قالت لك: هذا فوق فهمي. فقد أخبر اللهُ بتيسيره، وعلّق الإمامُ الوعدَ على الإقبال. فابدأ ثمّ احكم؛ فإنّ أكثر من يهجر النظر في القرآن يهجره على ظنٍّ لم يختبره.\nوالثاني: اجعل نصيبك منه يوميًّا وإن قلّ. فالوعدُ لمن أقبل، **والإقبالُ يكون بالمداومة لا بالدفعة**. وقد قال الإمامُ: «إذا طلبه العبدُ أُعين عليه»؛ فالعونُ يأتي في أثناء الطلب لا قبله.\nوالثالث: **وسّع ما تطلبه فيه**. فلا تقرأه للموعظة وحدها؛ فقد عدّ الإمامُ في «الذكر» الأحكامَ والعقائدَ والأخبارَ والعبر. فاسأل عند كلّ مقطع: ما الذي يُذكّرني به هذا؟ أحكمًا أم خبرًا أم عبرة؟","grade":"ma'thur","source":"تفسيرُ السعديّ للتيسير («أي: ولقد يسرنا وسهلنا هذا القرآن الكريم، ألفاظه للحفظ والأداء، ومعانيه للفهم والعلم»)، وتعليلُه («لأنه أحسن الكلام لفظا، وأصدقه معنى، وأبينه تفسيرا»)، وتعليقُه على الإقبال («فكل من أقبل عليه يسر الله عليه مطلوبه غاية التيسير، وسهله عليه»)، وتوسيعُه للذكر («والذكر شامل لكل ما يتذكر به العاملون من الحلال والحرام، وأحكام الأمر والنهي، وأحكام الجزاء والمواعظ والعبر، والعقائد النافعة والأخبار الصادقة»)، وحكمُه على العلم («ولهذا كان علم القرآن حفظا وتفسيرا، أسهل العلوم، وأجلها على الإطلاق»، «وهو العلم النافع الذي إذا طلبه العبد أعين عليه»)، ونقلُه عن بعض السلف («هل من طالب علم فيعان»): كلُّها بنصّها في تفسير السعديّ (٥٤:١٧).","honesty":"وممّا يجب أن يُقال:\nتفريقُنا في التمهيد بين جهتي اللفظ والمعنى، **تمهيدٌ منّا**، بنيناه على تفريق السعديّ في تفسير التيسير؛ وليس نصًّا له.\nوأمّا قولُنا إنّ الأصل أنّ أجلّ العلوم أصعبُها، فتحريرٌ منّا لبيان موضع العجب في جمع الوصفين؛ ومن رأى أنّا وسّعنا فليردّه.\nوأمّا القولُ المنقول عن بعض السلف فنقلناه كما ساقه السعديُّ غيرَ مسمًّى، ولم نتتبّع قائلَه ولا إسنادَه.\nوأمّا قولُنا إنّ العون يأتي في أثناء الطلب لا قبله، **فاستنباطٌ منّا** من قوله «إذا طلبه العبد أعين عليه»."}}]},{"title":"قصةُ عادٍ وإهلاكُهم بالريحِ الصرصر","range":[18,22],"theme":"تكذيبُ عادٍ وإرسالُ الريحِ الصرصرِ عليهم في يومِ نحسٍ مستمرٍّ تنزع الناسَ كأنهم أعجازُ نخلٍ منقعر، مع تكرارِ لازمتي التهويلِ للعذابِ والحثِّ على التذكّرِ بالقرآن","verses":[{"n":18,"reflection":{"text":"«كذبت عاد فكيف كان عذابي ونذر»: كذّبت عادٌ رسولها، فكيف كان عذابي لهم ونذري؟ ففي هذا التذكيرُ بتكذيبِ عادٍ وعذابهم؛ فاعتبر بتكذيبِ عادٍ وعذابهم، فالتكذيبُ يورث العذاب، فاحذره واتّعظ بنذارةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بتكذيبِ عادٍ وعذابهم، والحذرُ من التكذيب."},"action":{"text":"تأمّل تكذيبَ عاد: كذّبت عادٌ، قومُ هودٍ، رسولهم هودًا عليه السلام؛ فكيف كان عذابي لهم ونُذُري، أي إنذاري قبل العذاب؟ استفهامٌ للتهويل «كذبت عاد فكيف كان عذابي ونذر»؛ ففي هذا التذكيرُ بتكذيبِ عادٍ لنبيّهم، والتهويلِ لعذابهم بعد الإنذار؛ فكذّبوا فأُهلِكوا؛ فاعتبر أنت بتكذيبِ عادٍ لنبيّهم وما حلّ بهم من العذاب؛ فالتكذيبُ يورث العذابَ الشديد؛ وأمّا عادٌ فأُهلِكوا بريحٍ صرصرٍ عاتية؛ فاحذر التكذيبَ الذي أهلك عادًا؛ واتّعظ بنذارةِ الله التي سبقت عذابهم؛ فمن اتّعظ بتكذيبِ عادٍ وعذابهم نجا، ومن سلك سبيلهم هلك؛ فاجعل الاعتبارَ بتكذيبِ عادٍ والحذرَ من التكذيبِ دأبك."}},{"n":19,"reflection":{"text":"«إنا أرسلنا عليهم ريحا صرصرا في يوم نحس مستمر»: إنا أرسلنا على عادٍ ريحًا شديدةَ البردِ والصوتِ في يومِ شؤمٍ دائمٍ عليهم؛ ففي هذا بيانُ عذابِ عادٍ بالريح؛ فاعتبر بعذابِ عادٍ بالريح، فقدرةُ الله على العذابِ عظيمة، فاتّق الله واحذر عذابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعذابِ عادٍ بالريح، والحذرُ من عذابِ الله."},"action":{"text":"تأمّل عذابَ عادٍ بالريح: إنا أرسلنا على عادٍ ريحًا صرصرًا، أي شديدةَ البردِ والهبوبِ والصوت، في يومِ نحسٍ، أي شؤمٍ عليهم، مستمرٍّ دائمِ النحوسةِ عليهم حتى أهلكتهم «إنا أرسلنا عليهم ريحا صرصرا في يوم نحس مستمر»؛ ففي هذا بيانُ عذابِ عادٍ بالريحِ الشديدةِ في يومِ شؤمٍ دائم؛ فأهلكهم الله بالريحِ العاتية؛ فاعتبر أنت بعذابِ عادٍ بالريحِ رغمَ قوّتهم؛ سخّرها عليهم سبعَ ليالٍ وثمانيةَ أيامٍ حسومًا؛ ريحٌ فيها عذابٌ أليم، تدمّر كلَّ شيء؛ فقدرةُ الله على العذابِ عظيمةٌ لا تُقاوَم؛ فاتّق الله واحذر عذابه وبطشه؛ فمن اتّقى الله وحذر عذابه نجا، ومن أمن مكره هلك؛ فاجعل الاعتبارَ بعذابِ عادٍ والحذرَ من عذابِ الله دأبك."}},{"n":20,"reflection":{"text":"«تنزع الناس كأنهم أعجاز نخل منقعر»: تقتلع الريحُ الناسَ فتصرعهم كأنهم أصولُ نخلٍ منقلعٍ عن مغارسه؛ ففي هذا تصويرُ شدّةِ عذابِ عاد؛ فاعتبر بشدّةِ عذابِ الله الذي اقتلع عادًا، فعذابُ الله شديد، فاحذر أسبابَ سخطه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بشدّةِ عذابِ الله، واجتنابُ أسبابِ سخطه."},"action":{"text":"تأمّل شدّةَ عذابِ عاد: تنزع تلك الريحُ الناسَ من مواضعهم وتقتلعهم وتصرعهم على الأرضِ موتى؛ فكانوا كأنهم أعجازُ نخلٍ، أي أصولُ نخلٍ، منقعرٍ منقلعٍ عن مغارسه، ساقطٍ على الأرض «تنزع الناس كأنهم أعجاز نخل منقعر»؛ ففي هذا تصويرُ شدّةِ عذابِ عادٍ بالريح، حيث اقتلعتهم فصرعتهم كالنخلِ المنقلع؛ فأهلكتهم وصرعتهم؛ فاعتبر أنت بشدّةِ عذابِ الله الذي اقتلع عادًا رغمَ قوّتهم وضخامتهم؛ فترى القومَ فيها صرعى كأنهم أعجازُ نخلٍ خاوية؛ فعذابُ الله شديدٌ مهلكٌ لا يُقاوَم؛ فاحذر أنت أسبابَ سخطِ الله وعذابه من الكفرِ والتكذيبِ والمعاصي؛ فمن اجتنب أسبابَ السخطِ نجا، ومن ارتكبها هلك؛ فاجعل الاعتبارَ بشدّةِ عذابِ الله واجتنابَ أسبابِ سخطه دأبك."}},{"n":21,"reflection":{"text":"«فكيف كان عذابي ونذر»: فكيف كان عذابي لعادٍ ونذري؟ ففي هذا تكرارُ التهويلِ لعذابِ عاد؛ فتأمّل شدّةَ عذابِ الله لعادٍ واتّعظ بنذارته، فعذابُ الله شديد، فاحذر أن يصيبك مثله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بعذابِ عادٍ ونذارةِ الله، والحذرُ منها."},"action":{"text":"تأمّل تكرارَ التهويل: فكيف كان عذابي لعادٍ المكذّبين، ونُذُري، أي إنذاري لهم قبله؟ استفهامٌ مكرّرٌ للتهويلِ والتعظيم «فكيف كان عذابي ونذر»؛ ففي هذا تكرارُ التهويلِ لعذابِ عادٍ بعد الإنذار؛ فكان عذابهم شديدًا بعد إنذارٍ بالغ؛ فتأمّل أنت شدّةَ عذابِ الله لعادٍ، وأنه أنذرهم قبله؛ فعذابُ الله شديدٌ لمن كذّب؛ ونذارتُه حقٌّ سبقت عذابه؛ (وتكرارُ هذه اللازمةِ في كلِّ قصّةٍ تأكيدٌ للتهويلِ والاتّعاظ)؛ فاحذر أنت أن يصيبك مثلُ عذابِ عاد، واتّعظ بالنذارةِ قبل العذاب؛ فمن اتّعظ بالنذارةِ نجا، ومن أعرض عنها ذاق العذاب؛ فاجعل الاتّعاظَ بعذابِ عادٍ ونذارةِ الله والحذرَ منها دأبك."}},{"n":22,"reflection":{"text":"«ولقد يسرنا القرآن للذكر فهل من مدكر»، ولقد سهّلنا القرآنَ للذكر، فهل من متّعظ؟ ففي هذا تكرارُ بيانِ تيسيرِ القرآنِ والحثِّ على التذكّر؛ فأقبل على القرآنِ المُيسَّرِ متذكّرًا، وكن من المدّكرين، فتكرارُ الحثِّ تأكيدٌ لأهمّيةِ التذكّرِ بالقرآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على القرآنِ متذكّرًا، وإدراكُ أهمّيةِ التذكّرِ به."},"action":{"text":"تأمّل تكرارَ الحثِّ على التذكّر: ولقد يسّرنا وسهّلنا القرآنَ للذكرِ والحفظِ والفهمِ والاتّعاظِ والعمل؛ فهل من مدّكرٍ متّعظٍ يتذكّر به؟ «ولقد يسرنا القرآن للذكر فهل من مدكر»؛ ففي هذا تكرارُ بيانِ تيسيرِ القرآنِ للذكر، والحثِّ على التذكّرِ به والعملِ بمقتضاه؛ (وتكرارُها بعد كلِّ قصّةٍ تأكيدٌ لأهمّيةِ الاتّعاظِ بالقرآنِ والقصص)؛ فالقرآنُ ميسَّرٌ لمن أراد الذكرى؛ فأقبل أنت على القرآنِ المُيسَّرِ متذكّرًا متّعظًا عاملًا؛ واتّعظ بقصصه وعبره؛ لقد كان في قصصهم عبرةٌ لأولي الألباب؛ فتكرارُ الحثِّ على التذكّرِ تأكيدٌ لأهمّيته؛ فكن من المدّكرين المتّعظين بالقرآن؛ فمن أقبل على القرآنِ متذكّرًا اهتدى، ومن أعرض عنه ضلّ؛ فاجعل الإقبالَ على القرآنِ متذكّرًا وإدراكَ أهمّيةِ التذكّرِ به دأبك."}}]},{"title":"قصةُ ثمودَ وعقرِ الناقةِ وإهلاكُهم بالصيحة","range":[23,32],"theme":"تكذيبُ ثمودَ واستكبارُهم على اتّباعِ البشرِ الواحدِ وحسدُهم له، ووعيدُهم بأنهم سيعلمون من الكذّاب، وابتلاؤهم بالناقةِ فتنةً وقسمةِ الماءِ فعقروها، وإهلاكُهم بصيحةٍ واحدةٍ فكانوا كهشيمِ المحتظر، مع تكرارِ لازمتي التهويلِ والحثِّ على التذكّر","verses":[{"n":23,"reflection":{"text":"«كذبت ثمود بالنذر»: كذّبت ثمودُ بالرسلِ والإنذارات؛ ففي هذا التذكيرُ بتكذيبِ ثمود؛ فاعتبر بتكذيبِ ثمودَ للنُّذُر، فالتكذيبُ سببُ الهلاك، فاحذره واقبل نذارةَ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ نذارةِ الله، والحذرُ من التكذيبِ الموجبِ للهلاك."},"action":{"text":"تأمّل تكذيبَ ثمود: كذّبت ثمودُ، قومُ صالح، بالنُّذُر، أي بالرسلِ والإنذاراتِ التي جاءتهم، أو بنبيّهم صالحٍ عليه السلام «كذبت ثمود بالنذر»؛ ففي هذا التذكيرُ بتكذيبِ ثمودَ للنُّذُرِ والرسل؛ فكذّبوا صالحًا وما أنذرهم به؛ فاعتبر أنت بتكذيبِ ثمودَ للنُّذُرِ والرسل؛ فالتكذيبُ بالرسلِ والإنذاراتِ سببُ الهلاكِ والعذاب؛ كذّبت ثمودُ المرسلين؛ فأخذتهم الصاعقةُ؛ فاحذر التكذيبَ الذي أهلك ثمود؛ واقبل نذارةَ الله ورسله؛ فمن قبل النذارةَ واتّعظ بها نجا، ومن كذّب بها هلك؛ فاجعل قبولَ نذارةِ الله والحذرَ من التكذيبِ دأبك."}},{"n":24,"reflection":{"text":"«فقالوا أبشرا منا واحدا نتبعه إنا إذا لفي ضلال وسعر»: فقالوا: أبشرًا منّا فردًا نتّبعه؟ إنا إذًا لفي ضلالٍ وجنون؛ ففي هذا بيانُ استكبارِ ثمودَ على اتّباعِ الرسولِ البشري؛ فلا تستكبر عن اتّباعِ الحقِّ الذي يحمله بشرٌ مثلك، فالحقُّ يُتَّبَع لذاته، فاتّبعه ولو حمله بشر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الحقِّ ولو حمله بشر، وتركُ الاستكبار."},"action":{"text":"تأمّل استكبارَ ثمود: فقالت ثمودُ منكرين مستكبرين: أبشرًا منّا واحدًا فردًا، أي رجلًا من جنسنا لا مزيّةَ له، نتّبعه ونطيعه؟ إنا إن اتّبعناه إذًا لفي ضلالٍ عن الصوابِ وسُعُرٍ، أي جنونٍ وعناء «فقالوا أبشرا منا واحدا نتبعه إنا إذا لفي ضلال وسعر»؛ ففي هذا بيانُ استكبارِ ثمودَ عن اتّباعِ نبيّهم صالحٍ لكونه بشرًا مثلهم؛ فاستكبروا عن اتّباعِ البشر؛ فلا تستكبر أنت عن اتّباعِ الحقِّ الذي يحمله بشرٌ مثلك؛ فالحقُّ يُتَّبَع لذاته لا لجنسِ حامله؛ وما منع الناسَ أن يؤمنوا... إلا أن قالوا أبعث الله بشرًا رسولًا؛ قل إنما أنا بشرٌ مثلكم يوحى إليّ؛ فالاستكبارُ عن اتّباعِ الحقِّ لكونِ حامله بشرًا من صفاتِ المكذّبين؛ فاتّبع الحقَّ ولو حمله بشرٌ مثلك؛ فمن اتّبع الحقَّ ولو من بشرٍ اهتدى، ومن استكبر عنه ضلّ؛ فاجعل اتّباعَ الحقِّ ولو حمله بشرٌ وتركَ الاستكبارِ دأبك."}},{"n":25,"reflection":{"text":"«أألقي الذكر عليه من بيننا بل هو كذاب أشر»: أخُصَّ بالوحيِ من بيننا؟ بل هو كذّابٌ متكبّرٌ بطر؛ ففي هذا بيانُ حسدِ ثمودَ ورميهم الرسولَ بالكذب؛ فاحذر الحسدَ ورميَ أهلِ الحقِّ بالكذب، فاقبل فضلَ الله على من اصطفاه، فالحسدُ يعمي عن الحق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ فضلِ الله على من اصطفاه، وتركُ الحسدِ ورميِ الحقِّ بالكذب."},"action":{"text":"تأمّل حسدَ ثمود: قالت ثمودُ حسدًا واستنكارًا: أأُلقِي الذكرُ والوحيُ عليه، أي على صالحٍ، من بيننا نحن الأشرافَ الكثيرين؟ لِمَ خُصَّ هو بالوحي؟ بل هو كذّابٌ في دعواه النبوّة، أشِرٌ، أي متكبّرٌ بطِرٌ يريد التعاظمَ علينا «أألقي الذكر عليه من بيننا بل هو كذاب أشر»؛ ففي هذا بيانُ حسدِ ثمودَ لنبيّهم على اصطفائه بالوحي، ورميهم إياه بالكذبِ والكبر؛ فحسدوه على النبوّةِ ورموه بالكذب؛ فاحذر أنت الحسدَ لمن اصطفاه الله بفضلٍ أو علمٍ أو دين؛ واحذر رميَ أهلِ الحقِّ بالكذبِ والتهم؛ أم يحسدون الناسَ على ما آتاهم الله من فضله؛ الله أعلمُ حيث يجعل رسالته؛ فاقبل أنت فضلَ الله على من اصطفاه واختاره؛ فالحسدُ يعمي عن الحقِّ ويحمل على ردّه؛ فمن قبل فضلَ الله على أوليائه سلم، ومن حسدهم ورماهم بالتهم هلك؛ فاجعل قبولَ فضلِ الله على من اصطفاه وتركَ الحسدِ دأبك."}},{"n":26,"reflection":{"text":"«سيعلمون غدا من الكذاب الأشر»: سيعلمون غدًا (عند العذابِ أو القيامة) من الكذّابُ المتكبّر؛ ففي هذا وعيدٌ لثمودَ وتسليةٌ لصالح؛ فاعلم أنّ الحقَّ سيظهر والكاذبَ سيُفضَح، فاثبت على الحقِّ فالعاقبةُ له، فالله يكشف الكاذبَ من الصادق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقّ، وإدراكُ أنّ الله يكشف الصادقَ من الكاذب."},"action":{"text":"تأمّل الوعيدَ لثمود: قال الله لصالح تسليةً ووعيدًا لهم: سيعلم قومك ثمودُ غدًا، أي عند نزولِ العذابِ عليهم قريبًا، أو يومَ القيامة، من الكذّابُ الأشِرُ المتكبّر: أهو صالحٌ الصادقُ، أم هم المكذّبون؟ «سيعلمون غدا من الكذاب الأشر»؛ ففي هذا وعيدٌ لثمودَ بأنهم سيعلمون حقيقةَ الأمرِ عند العذاب، وتسليةٌ لصالحٍ وتأكيدٌ لصدقه؛ فسيظهر الصادقُ من الكاذب؛ فاعلم أنت أنّ الحقَّ سيظهر والكاذبَ سيُفتضَح لا محالة؛ فاثبت على الحقِّ فالعاقبةُ له؛ وسيعلم الذين ظلموا أيَّ منقلبٍ ينقلبون؛ ولتعلمنّ نبأه بعد حين؛ فالله يكشف الصادقَ من الكاذبِ ويُظهِر الحق؛ فمن ثبت على الحقِّ ظهر صدقه، ومن كذّب فُضِح؛ فاجعل الثباتَ على الحقِّ وإدراكَ أنّ الله يكشف الصادقَ من الكاذبِ دأبك."}},{"n":27,"reflection":{"text":"«إنا مرسلو الناقة فتنة لهم فارتقبهم واصطبر»: إنا مرسلو الناقةِ (آيةً) اختبارًا لهم، فارتقبهم واصبر؛ ففي هذا بيانُ ابتلاءِ ثمودَ بالناقةِ والأمرِ بالصبر؛ فاعلم أنّ الله يبتلي الناسَ ليتبيّن المؤمنُ من الكافر، فاصبر على الابتلاء، فالابتلاءُ يميّز الصادق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الابتلاء، وإدراكُ أنه يميّز المؤمن."},"action":{"text":"تأمّل ابتلاءَ ثمود: قال الله لصالح: إنا مرسلو الناقةِ، أي مُخرِجوها من الصخرةِ آيةً ومعجزة، فتنةً واختبارًا لهم، لنبتليهم أيؤمنون أم يكفرون؟ فارتقبهم، أي انتظر ما يصنعون وما يحلُّ بهم، واصطبر على أذاهم وتكذيبهم «إنا مرسلو الناقة فتنة لهم فارتقبهم واصطبر»؛ ففي هذا بيانُ ابتلاءِ الله ثمودَ بالناقةِ اختبارًا، والأمرِ لصالحٍ بالصبرِ والانتظار؛ فابتلاهم بالناقةِ ليتبيّن المؤمنُ من الكافر؛ فاعلم أنت أنّ الله يبتلي الناسَ بالآياتِ والتكاليفِ ليتبيّن المؤمنُ من الكافر، والصادقُ من الكاذب؛ وليبلوَ الله ما في صدوركم؛ أحسب الناسُ أن يُتركوا أن يقولوا آمنّا وهم لا يُفتَنون؛ فاصبر أنت على الابتلاءِ والأذى في سبيلِ الله؛ فالابتلاءُ يميّز الصادقَ من الكاذب، والمؤمنَ من المنافق؛ فمن صبر على الابتلاءِ ظهر صدقه، ومن جزع ظهر ضعفه؛ فاجعل الصبرَ على الابتلاءِ وإدراكَ أنه يميّز المؤمنَ دأبك."}},{"n":28,"reflection":{"text":"«ونبئهم أن الماء قسمة بينهم كل شرب محتضر»، وأخبرهم أنّ الماءَ مقسومٌ بينهم وبين الناقة، كلُّ نصيبٍ يحضره أهله؛ ففي هذا بيانُ العدلِ في القسمةِ والابتلاء؛ فاعلم أنّ الله يقسم بعدله ويبتلي بحكمته، فارضَ بقسمةِ الله، فالعدلُ والحكمةُ في قسمةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرضا بقسمةِ الله، وإدراكُ عدلِه وحكمتِه فيها."},"action":{"text":"تأمّل العدلَ في القسمة: وأخبر، يا صالحُ، قومك ثمودَ أنّ الماءَ قسمةٌ مقسومةٌ بينهم وبين الناقة: يومٌ لهم ويومٌ للناقةِ تشربه؛ كلُّ شِربٍ ونصيبٍ من الماءِ محتضرٌ، أي يحضره أهله في نوبتهم «ونبئهم أن الماء قسمة بينهم كل شرب محتضر»؛ ففي هذا بيانُ قسمةِ الماءِ بين ثمودَ والناقةِ بالعدل، اختبارًا لهم؛ فقسم الله الماءَ بينهم بالعدل؛ فاعلم أنت أنّ الله يقسم أرزاقَ الخلقِ وأمورهم بعدله وحكمته؛ ويبتليهم بذلك؛ نحن قسمنا بينهم معيشتهم في الحياةِ الدنيا؛ ونبّئهم أنّ الماءَ قسمةٌ بينهم؛ فارضَ أنت بقسمةِ الله لك في الرزقِ والأمور؛ فالعدلُ والحكمةُ في كلِّ ما يقسمه الله؛ فمن رضي بقسمةِ الله اطمأنّ، ومن اعترض تعب؛ فاجعل الرضا بقسمةِ الله وإدراكَ عدلِه وحكمتِه دأبك."}},{"n":29,"reflection":{"text":"«فنادوا صاحبهم فتعاطى فعقر»: فنادوا صاحبهم (قدارَ بن سالف) فتناول الناقةَ فعقرها؛ ففي هذا بيانُ جرأةِ ثمودَ على عقرِ الناقةِ آيةِ الله؛ فاحذر الجرأةَ على حدودِ الله وآياته، فالجرأةُ على معصيةِ الله سببُ الهلاك، فعظّم حرماتِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ حرماتِ الله، والحذرُ من الجرأةِ على معصيته."},"action":{"text":"تأمّل جرأةَ ثمود: فنادى ثمودُ صاحبهم وأشقاهم (قدارَ بنَ سالف) ليعقر الناقة؛ فتعاطى، أي تناول الناقةَ بيده وجرؤ عليها، فعقرها وقتلها؛ فاجترؤوا على آيةِ الله ونهيه «فنادوا صاحبهم فتعاطى فعقر»؛ ففي هذا بيانُ جرأةِ ثمودَ على عقرِ الناقةِ التي هي آيةُ الله، مخالفةً لأمرِ نبيّهم؛ فعقروها فاستحقّوا العذاب؛ فاحذر أنت الجرأةَ على حدودِ الله وآياته ونواهيه؛ فالجرأةُ على معصيةِ الله وانتهاكِ حرماته سببُ الهلاكِ والعذاب؛ فعقروا الناقةَ وعتوا عن أمرِ ربّهم؛ فعظّم أنت حرماتِ الله وحدوده وآياته؛ ومن يعظّم حرماتِ الله فهو خيرٌ له عند ربّه؛ فمن عظّم حرماتِ الله نجا، ومن اجترأ على معصيته هلك؛ فاجعل تعظيمَ حرماتِ الله والحذرَ من الجرأةِ على معصيته دأبك."}},{"n":30,"reflection":{"text":"«فكيف كان عذابي ونذر»: فكيف كان عذابي لثمودَ ونذري؟ ففي هذا تكرارُ التهويلِ لعذابِ ثمود؛ فتأمّل شدّةَ عذابِ الله لثمودَ واتّعظ بنذارته، فعذابُ الله شديد، فاحذر أن يصيبك مثله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بعذابِ ثمودَ ونذارةِ الله، والحذرُ منها."},"action":{"text":"تأمّل تكرارَ التهويل: فكيف كان عذابي لثمودَ المكذّبين العاقرين للناقة، ونُذُري، أي إنذاري لهم قبله؟ استفهامٌ مكرّرٌ للتهويلِ والتعظيم «فكيف كان عذابي ونذر»؛ ففي هذا تكرارُ التهويلِ لعذابِ ثمودَ بعد الإنذار؛ فكان عذابهم شديدًا بعد إنذارٍ بالغ؛ فتأمّل أنت شدّةَ عذابِ الله لثمودَ بالصيحةِ والرجفة، وأنه أنذرهم قبله؛ فعذابُ الله شديدٌ لمن كذّب واجترأ؛ ونذارتُه حقٌّ سبقت عذابه؛ فاحذر أنت أن يصيبك مثلُ عذابِ ثمود، واتّعظ بالنذارةِ قبل العذاب؛ فمن اتّعظ بالنذارةِ نجا، ومن أعرض عنها ذاق العذاب؛ فاجعل الاتّعاظَ بعذابِ ثمودَ ونذارةِ الله والحذرَ منها دأبك."}},{"n":31,"reflection":{"text":"«إنا أرسلنا عليهم صيحة واحدة فكانوا كهشيم المحتظر»: إنا أرسلنا على ثمودَ صيحةً واحدةً فصاروا كالنباتِ اليابسِ المتحطّم الذي يجعله صاحبُ الحظيرة؛ ففي هذا بيانُ هلاكِ ثمودَ بصيحةٍ واحدة؛ فاعلم أنّ الله يهلك المكذّبين بأيسرِ شيءٍ من جنده، فلا تأمن عذابه، فقدرةُ الله عظيمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الأمنِ من عذابِ الله، وإدراكُ عظمةِ قدرته."},"action":{"text":"تأمّل هلاكَ ثمودَ بصيحة: إنا أرسلنا على ثمودَ صيحةً واحدةً (صيحةَ العذابِ من جبريلَ أو الصاعقة)؛ فأهلكتهم جميعًا، فكانوا كهشيمِ المحتظِر، أي كالنباتِ اليابسِ المتحطّمِ المتكسّرِ الذي يجعله صاحبُ الحظيرةِ لغنمه «إنا أرسلنا عليهم صيحة واحدة فكانوا كهشيم المحتظر»؛ ففي هذا بيانُ هلاكِ ثمودَ جميعًا بصيحةٍ واحدة، حتى صاروا كالهشيمِ اليابس؛ فأهلكهم الله بصيحةٍ واحدةٍ يسيرةٍ من جنده؛ فاعلم أنت أنّ الله يهلك المكذّبين بأيسرِ شيءٍ من جنده: صيحةٍ أو ريحٍ أو رجفة؛ إن كانت إلا صيحةً واحدةً فإذا هم خامدون؛ فأخذتهم الصاعقةُ؛ فلا تأمن أنت عذابَ الله ومكره؛ فقدرةُ الله عظيمةٌ يهلك بها الأممَ بأيسرِ سبب؛ فلا يأمن مكرَ الله إلا القومُ الخاسرون؛ فمن خاف عذابَ الله واستعدّ نجا، ومن أمنه هلك؛ فاجعل عدمَ الأمنِ من عذابِ الله وإدراكَ عظمةِ قدرته دأبك."}},{"n":32,"reflection":{"text":"«ولقد يسرنا القرآن للذكر فهل من مدكر»، ولقد سهّلنا القرآنَ للذكر، فهل من متّعظ؟ ففي هذا تكرارُ الحثِّ على التذكّرِ بالقرآن؛ فأقبل على القرآنِ المُيسَّرِ متذكّرًا، وكن من المدّكرين، فتكرارُ الحثِّ يؤكّد وجوبَ الاتّعاظِ بالقرآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على القرآنِ متذكّرًا، والاتّعاظُ به."},"action":{"text":"تأمّل تكرارَ الحث: ولقد يسّرنا وسهّلنا القرآنَ للذكرِ والحفظِ والفهمِ والاتّعاظِ والعمل؛ فهل من مدّكرٍ متّعظٍ يتذكّر به؟ «ولقد يسرنا القرآن للذكر فهل من مدكر»؛ ففي هذا تكرارُ بيانِ تيسيرِ القرآنِ للذكر، والحثِّ على التذكّرِ به بعد كلِّ قصّة؛ فتكرارُها تأكيدٌ لوجوبِ الاتّعاظِ بالقرآنِ والقصص؛ فالقرآنُ ميسَّرٌ لمن أراد الذكرى؛ فأقبل أنت على القرآنِ المُيسَّرِ متذكّرًا متّعظًا عاملًا؛ واتّعظ بقصصِ الأممِ التي فيه؛ أفلا يتدبّرون القرآن؛ لقد كان في قصصهم عبرةٌ لأولي الألباب؛ فكن من المدّكرين المتّعظين بالقرآنِ وقصصه؛ فمن أقبل على القرآنِ متذكّرًا اهتدى، ومن أعرض عنه ضلّ؛ فاجعل الإقبالَ على القرآنِ متذكّرًا والاتّعاظَ به دأبك."}}]},{"title":"قصةُ قومِ لوطٍ وإهلاكُهم بالحاصب","range":[33,40],"theme":"تكذيبُ قومِ لوطٍ بالنُّذُر، وإرسالُ الحاصبِ عليهم إلا آلَ لوطٍ نُجّوا بسحرٍ نعمةً من الله كذلك يُجزى من شكر، وإنذارُهم بالبطشةِ فتماروا، ومراودتُهم عن ضيفه فطُمِست أعينهم وصبّحهم عذابٌ مستقر، مع تكرارِ لازمتي «فذوقوا عذابي ونذر» و«ولقد يسرنا القرآن للذكر فهل من مدكر»","verses":[{"n":33,"reflection":{"text":"«كذبت قوم لوط بالنذر»: كذّبت قومُ لوطٍ بالإنذاراتِ والرسل؛ ففي هذا التذكيرُ بتكذيبِ قومِ لوط؛ فاعتبر بتكذيبِ قومِ لوطٍ للنُّذُر، فالتكذيبُ سببُ الهلاك، فاقبل نذارةَ الله واحذر التكذيب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ نذارةِ الله، والحذرُ من التكذيبِ الموجبِ للهلاك."},"action":{"text":"تأمّل تكذيبَ قومِ لوط: كذّبت قومُ لوطٍ بالنُّذُر، أي بالإنذاراتِ التي جاءتهم على لسانِ نبيّهم لوطٍ عليه السلام، أو بالرسلِ عمومًا «كذبت قوم لوط بالنذر»؛ ففي هذا التذكيرُ بتكذيبِ قومِ لوطٍ للنُّذُرِ والرسل؛ فكذّبوا لوطًا وما أنذرهم به من عاقبةِ فاحشتهم؛ فاعتبر أنت بتكذيبِ قومِ لوطٍ للنُّذُر؛ فالتكذيبُ بالرسلِ والإنذاراتِ سببُ الهلاك؛ كذّبت قومُ لوطٍ المرسلين؛ إنا مرسلون إلى قومٍ مجرمين؛ فاقبل أنت نذارةَ الله ورسله واتّعظ بها؛ واحذر التكذيبَ الذي أهلك قومَ لوط؛ فمن قبل النذارةَ نجا، ومن كذّب بها هلك؛ فاجعل قبولَ نذارةِ الله والحذرَ من التكذيبِ دأبك."}},{"n":34,"reflection":{"text":"«إنا أرسلنا عليهم حاصبا إلا آل لوط نجيناهم بسحر»: إنا أرسلنا على قومِ لوطٍ ريحًا ترميهم بالحجارة، إلا آلَ لوطٍ نجّيناهم بآخرِ الليل؛ ففي هذا بيانُ عذابِ قومِ لوطٍ ونجاةِ آلِ لوط؛ فاعلم أنّ الله يهلك المجرمين وينجّي المؤمنين، فآمن لتكون من الناجين، فالإيمانُ سببُ النجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ سبيلُ النجاة، وإدراكُ أنّ الله ينجّي المؤمنين."},"action":{"text":"تأمّل عذابَ قومِ لوطٍ ونجاةَ آله: إنا أرسلنا على قومِ لوطٍ حاصبًا، أي ريحًا أو عذابًا يرميهم بالحجارةِ من سِجّيل؛ إلا آلَ لوطٍ (أهله المؤمنين) نجّيناهم بسحرٍ، أي بآخرِ الليلِ قبل نزولِ العذاب «إنا أرسلنا عليهم حاصبا إلا آل لوط نجيناهم بسحر»؛ ففي هذا بيانُ عذابِ قومِ لوطٍ بالحجارة، ونجاةِ آلِ لوطٍ المؤمنين قبل العذاب؛ فأهلك المجرمين ونجّى المؤمنين؛ فاعلم أنت أنّ الله يهلك المجرمين وينجّي المؤمنين المتّقين؛ فأنجيناه وأهله إلا امرأته؛ فأسرِ بأهلك بقطعٍ من الليل؛ فالإيمانُ والتقوى سببُ النجاةِ من العذاب؛ فآمن أنت بالله واتّقه لتكون من الناجين؛ فمن آمن واتّقى نجا، ومن كفر وأجرم هلك؛ فاجعل الإيمانَ والتقوى سبيلَ نجاتك من العذاب."}},{"n":35,"reflection":{"text":"«نعمة من عندنا كذلك نجزي من شكر»: نجّيناهم نعمةً من عندنا، كذلك نجزي من شكر نعمتنا؛ ففي هذا بيانُ أنّ النجاةَ جزاءُ الشكر؛ فاشكر نعمَ الله لتنال جزاءَ الشاكرين، فالشكرُ سببُ النجاةِ والنعمة، فاجعل الشكرَ دأبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمِ الله لنيلِ جزاءِ الشاكرين والنجاة."},"action":{"text":"تأمّل أنّ النجاةَ جزاءُ الشكر: نجّينا آلَ لوطٍ نعمةً وإحسانًا من عندنا عليهم؛ كذلك، كما جزينا آلَ لوطٍ بالنجاة، نجزي من شكر نعمتنا وآمن وأطاع، بالنجاةِ والإكرام «نعمة من عندنا كذلك نجزي من شكر»؛ ففي هذا بيانُ أنّ نجاةَ آلِ لوطٍ نعمةٌ من الله، وأنّ ذلك جزاءُ من شكر نعمَ الله؛ فبشكرهم وإيمانهم نجّاهم؛ فاعلم أنت أنّ شكرَ نعمِ الله سببُ النجاةِ والنعمةِ والإكرام؛ فاشكر نعمَ الله بالقلبِ اعترافًا، وباللسانِ ثناءً، وبالجوارحِ طاعةً؛ لئن شكرتم لأزيدنّكم؛ وسيجزي الله الشاكرين؛ ومن شكر فإنما يشكر لنفسه؛ فالشكرُ سببُ النجاةِ والنعمةِ ودوامها؛ فمن شكر نعمَ الله نجا ونال المزيد، ومن كفرها هلك وسُلِبها؛ فاجعل شكرَ نعمِ الله لنيلِ جزاءِ الشاكرين والنجاةِ دأبك."}},{"n":36,"reflection":{"text":"«ولقد أنذرهم بطشتنا فتماروا بالنذر»، ولقد أنذرهم لوطٌ بطشتنا وعذابنا، فشكّوا وجادلوا في الإنذار؛ ففي هذا بيانُ إعراضهم عن الإنذار؛ فاحذر الشكَّ والجدالَ في إنذارِ الله، فاقبل النذارةَ وصدّق بها، فالتماري في النذارةِ من صفاتِ المكذّبين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ نذارةِ الله والتصديقُ بها، وتركُ الشكِّ والجدال."},"action":{"text":"تأمّل إعراضَهم عن الإنذار: ولقد أنذر لوطٌ قومه بطشتنا وعذابنا الشديد إن أصرّوا على فاحشتهم؛ فتماروا بالنُّذُر، أي شكّوا وجادلوا وكذّبوا بالإنذار، ولم يصدّقوا «ولقد أنذرهم بطشتنا فتماروا بالنذر»؛ ففي هذا بيانُ أنّ لوطًا أنذر قومه، فشكّوا وجادلوا في إنذاره ولم يعتبروا؛ فتماروا بالنذارةِ وكذّبوها؛ فاحذر أنت الشكَّ والجدالَ والتماريَ في إنذارِ الله ووعيده؛ فاقبل النذارةَ وصدّق بها واتّعظ؛ فالتماري والشكُّ في نذارةِ الله من صفاتِ المكذّبين المعرضين؛ فبأيِّ آلاءِ ربّك تتمارى؛ فبأيِّ حديثٍ بعده يؤمنون؛ فمن قبل النذارةَ وصدّق بها نجا، ومن تمارى فيها وكذّبها هلك؛ فاجعل قبولَ نذارةِ الله والتصديقَ بها وتركَ الشكِّ دأبك."}},{"n":37,"reflection":{"text":"«ولقد راودوه عن ضيفه فطمسنا أعينهم فذوقوا عذابي ونذر»، ولقد راودوا لوطًا عن ضيفه (الملائكةِ) ليفعلوا بهم الفاحشة، فطمسنا أعينهم، فذوقوا عذابي وإنذاري؛ ففي هذا بيانُ جرأتهم على الفاحشةِ وعقوبتهم؛ فاحذر الجرأةَ على الفواحشِ وأذى الضيف، فالفاحشةُ توجب العذاب، فعظّم حرماتِ الله واحمِ ضيفك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الفواحشِ وإكرامُ الضيف، والحذرُ من عقوبةِ الجرأة."},"action":{"text":"تأمّل جرأتهم وعقوبتهم: ولقد راود قومُ لوطٍ لوطًا عن ضيفه، وهم الملائكةُ الذين جاؤوه في صورةِ شبابٍ حسان، ليفعلوا بهم الفاحشة؛ فطمسنا أعينهم، أي أعميناها فصارت بلا شقٍّ عقوبةً؛ فقيل لهم: فذوقوا عذابي ونُذُري، أي عذابي وعاقبةَ إنذاري «ولقد راودوه عن ضيفه فطمسنا أعينهم فذوقوا عذابي ونذر»؛ ففي هذا بيانُ جرأةِ قومِ لوطٍ على الفاحشةِ حتى مع ضيفِ نبيّهم، وعقوبتهم بطمسِ الأعين؛ فاجترؤوا على الفاحشةِ وأذى الضيف فعُوقِبوا؛ فاحذر أنت الجرأةَ على الفواحشِ ما ظهر منها وما بطن، وأذى الضيفِ وانتهاكَ حرمته؛ فالفاحشةُ والجرأةُ عليها توجب العذاب؛ ولا تقربوا الفواحشَ ما ظهر منها وما بطن؛ فعظّم حرماتِ الله، واحمِ ضيفك وأكرمه؛ فمن اجتنب الفواحشَ وأكرم الضيفَ نجا، ومن اجترأ عليها هلك؛ فاجعل اجتنابَ الفواحشِ وإكرامَ الضيفِ دأبك."}},{"n":38,"reflection":{"text":"«ولقد صبحهم بكرة عذاب مستقر»، ولقد أتاهم في الصباحِ باكرًا عذابٌ دائمٌ مستقرٌّ لا يزول؛ ففي هذا بيانُ نزولِ العذابِ بقومِ لوط؛ فاعتبر بعذابِ قومِ لوطٍ الذي أتاهم بغتة، فالعذابُ يأتي المجرمين حيث لا يحتسبون، فاحذر أسبابه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعذابِ قومِ لوط، والحذرُ من أسبابِ العذاب."},"action":{"text":"تأمّل نزولَ العذاب: ولقد صبّحهم، أي أتاهم في الصباحِ باكرًا وقتَ الغفلة، عذابٌ مستقرٌّ دائمٌ لا يزول عنهم، متّصلٌ بعذابِ الآخرة؛ فأخذهم بغتةً بالحجارةِ وقلبِ ديارهم «ولقد صبحهم بكرة عذاب مستقر»؛ ففي هذا بيانُ نزولِ العذابِ بقومِ لوطٍ باكرًا مستقرًّا؛ فأتاهم العذابُ بغتةً في الصباح؛ فاعتبر أنت بعذابِ قومِ لوطٍ الذي أتاهم بغتةً وقتَ الغفلة؛ فالعذابُ يأتي المجرمين حيث لا يحتسبون؛ أفأمِن أهلُ القرى أن يأتيهم بأسنا بياتًا وهم نائمون، أو أمِن أهلُ القرى أن يأتيهم بأسنا ضحًى وهم يلعبون؛ فاحذر أنت أسبابَ العذابِ من الفواحشِ والكفرِ والمعاصي؛ فمن اجتنب أسبابَ العذابِ نجا، ومن ارتكبها هلك؛ فاجعل الاعتبارَ بعذابِ قومِ لوطٍ والحذرَ من أسبابِ العذابِ دأبك."}},{"n":39,"reflection":{"text":"«فذوقوا عذابي ونذر»: فذوقوا عذابي وعاقبةَ إنذاري؛ ففي هذا تقريعُ قومِ لوطٍ بالعذاب؛ فاتّعظ بعاقبةِ من ذاق عذابَ الله بعد الإنذار، فالإنذارُ حجّةٌ فمن أعرض عنه ذاق العذاب، فاقبل النذارةَ لتنجو.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ النذارةِ للنجاة، والاتّعاظُ بعاقبةِ المعرضين."},"action":{"text":"تأمّل تقريعَ قومِ لوط: قيل لقومِ لوطٍ عند نزولِ العذابِ توبيخًا وتقريعًا: فذوقوا عذابي وعاقبةَ إنذاري الذي أنذركم به نبيّكم فكذّبتم «فذوقوا عذابي ونذر»؛ ففي هذا تقريعٌ لقومِ لوطٍ بالعذابِ بعد أن أُنذِروا فأعرضوا؛ فذاقوا العذابَ جزاءَ إعراضهم عن النذارة؛ فاتّعظ أنت بعاقبةِ من ذاق عذابَ الله بعد الإنذار؛ فالإنذارُ حجّةٌ قامت عليهم؛ رسلًا مبشّرين ومنذرين لئلا يكون للناسِ على الله حجّةٌ بعد الرسل؛ فمن أعرض عن النذارةِ بعد بلوغها ذاق العذاب؛ فاقبل أنت النذارةَ واتّعظ بها لتنجو؛ فمن قبل النذارةَ وعمل بها نجا، ومن أعرض عنها ذاق العذاب؛ فاجعل قبولَ النذارةِ للنجاةِ والاتّعاظَ بعاقبةِ المعرضين دأبك."}},{"n":40,"reflection":{"text":"«ولقد يسرنا القرآن للذكر فهل من مدكر»، ولقد سهّلنا القرآنَ للذكر، فهل من متّعظ؟ ففي هذا تكرارُ الحثِّ على التذكّرِ بالقرآن؛ فأقبل على القرآنِ المُيسَّرِ متذكّرًا، وكن من المدّكرين، فتكرارُ الحثِّ يؤكّد وجوبَ الاتّعاظِ بالقرآنِ وقصصه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على القرآنِ متذكّرًا، والاتّعاظُ بقصصه."},"action":{"text":"تأمّل تكرارَ الحث: ولقد يسّرنا وسهّلنا القرآنَ للذكرِ والحفظِ والفهمِ والاتّعاظِ والعمل؛ فهل من مدّكرٍ متّعظٍ يتذكّر به؟ «ولقد يسرنا القرآن للذكر فهل من مدكر»؛ ففي هذا تكرارُ بيانِ تيسيرِ القرآنِ للذكر، والحثِّ على التذكّرِ به بعد قصةِ قومِ لوط؛ فتكرارُها للمرّةِ الرابعةِ تأكيدٌ لوجوبِ الاتّعاظِ بالقرآنِ وقصصه؛ فالقرآنُ ميسَّرٌ لمن أراد الذكرى؛ فأقبل أنت على القرآنِ المُيسَّرِ متذكّرًا متّعظًا عاملًا؛ واتّعظ بقصصِ الأممِ المكذّبةِ فيه؛ لقد كان في قصصهم عبرةٌ لأولي الألباب؛ فكن من المدّكرين المتّعظين بالقرآنِ وقصصه؛ فمن أقبل على القرآنِ متذكّرًا اهتدى، ومن أعرض عنه ضلّ؛ فاجعل الإقبالَ على القرآنِ متذكّرًا والاتّعاظَ بقصصه دأبك."}}]},{"title":"آلُ فرعون، والتهديدُ لكفّارِ قريش، والقدر","range":[41,50],"theme":"مجيءُ النُّذُرِ آلَ فرعونَ فكذّبوا بآياتنا كلِّها فأُخِذوا أخذَ عزيزٍ مقتدر، والتهديدُ لكفّارِ قريشٍ بأنهم ليسوا خيرًا من المهلَكين ولا براءةَ لهم، وأنّ جمعهم سيُهزَم ويولّون الدبر بل الساعةُ موعدهم وهي أدهى وأمرّ، وأنّ المجرمين في ضلالٍ وسعرٍ يُسحَبون في النارِ على وجوههم، وتقريرِ أنّ كلَّ شيءٍ خُلِق بقدرٍ وأنّ أمرَ الله كلمحٍ بالبصر","verses":[{"n":41,"reflection":{"text":"«ولقد جاء آل فرعون النذر»، ولقد جاء آلَ فرعونَ الإنذاراتُ على لسانِ موسى وهارون؛ ففي هذا التذكيرُ بإنذارِ آلِ فرعون؛ فاعلم أنّ الله يُقيم الحجّةَ بالإنذارِ قبل العذاب، فاتّعظ بالإنذارِ ولا تعرض عنه، فالإنذارُ رحمةٌ وحجّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بالإنذار، وإدراكُ أنّ الله يُقيم الحجّةَ قبل العذاب."},"action":{"text":"تأمّل إنذارَ آلِ فرعون: ولقد جاء آلَ فرعونَ النُّذُرُ، أي الإنذاراتُ والآياتُ على لسانِ موسى وهارونَ عليهما السلام، يدعوانهم إلى الله وينذرانهم عذابه «ولقد جاء آل فرعون النذر»؛ ففي هذا التذكيرُ بإنذارِ آلِ فرعونَ على لسانِ موسى؛ فأقام الله الحجّةَ عليهم بالإنذارِ والآيات؛ فاعلم أنت أنّ الله يُقيم الحجّةَ على العبادِ بالإنذارِ والرسلِ قبل العذاب؛ رسلًا مبشّرين ومنذرين؛ وما كنّا معذّبين حتى نبعث رسولًا؛ فالإنذارُ رحمةٌ من الله وحجّةٌ عليهم؛ فاتّعظ أنت بالإنذارِ ولا تعرض عنه كما أعرض آلُ فرعون؛ فمن اتّعظ بالإنذارِ نجا، ومن أعرض عنه هلك؛ فاجعل الاتّعاظَ بالإنذارِ وإدراكَ أنّ الله يُقيم الحجّةَ قبل العذابِ دأبك."}},{"n":42,"reflection":{"text":"«كذبوا بآياتنا كلها فأخذناهم أخذ عزيز مقتدر»: كذّبوا بآياتنا كلِّها، فأخذناهم أخذَ عزيزٍ مقتدرٍ لا يُغالَب؛ ففي هذا بيانُ عذابِ آلِ فرعونَ وقدرةِ الله؛ فاعتبر بأخذِ الله للمكذّبين أخذَ عزيزٍ مقتدر، فقدرةُ الله لا تُقاوَم، فاحذر تكذيبَ الآياتِ لئلا يأخذك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بقدرةِ الله في أخذِ المكذّبين، والحذرُ من التكذيب."},"action":{"text":"تأمّل عذابَ آلِ فرعون: كذّب آلُ فرعونَ بآياتنا كلِّها التي جاءهم بها موسى (كاليدِ والعصا والطوفانِ والجرادِ وغيرها)؛ فأخذناهم أخذَ عزيزٍ، أي غالبٍ لا يُقهَر، مقتدرٍ لا يعجزه شيء؛ فأغرقهم في البحرِ أجمعين «كذبوا بآياتنا كلها فأخذناهم أخذ عزيز مقتدر»؛ ففي هذا بيانُ تكذيبِ آلِ فرعونَ بجميعِ الآيات، وأخذِ الله لهم أخذَ عزيزٍ مقتدر؛ فأهلكهم بقدرته التي لا تُغالَب؛ فاعتبر أنت بأخذِ الله للمكذّبين أخذَ عزيزٍ مقتدر؛ فقدرةُ الله لا تُقاوَم ولا تُغالَب؛ فأخذناهم بغتةً وهم لا يشعرون؛ وكذلك أخذُ ربّك إذا أخذ القرى وهي ظالمة؛ فاحذر أنت تكذيبَ آياتِ الله لئلا يأخذك أخذ عزيزٍ مقتدر؛ فمن آمن بآياتِ الله نجا، ومن كذّب بها أُخِذ؛ فاجعل الاعتبارَ بقدرةِ الله في أخذِ المكذّبين والحذرَ من التكذيبِ دأبك."}},{"n":43,"reflection":{"text":"«أكفاركم خير من أولئكم أم لكم براءة في الزبر»: أكفاركم، يا معشر قريش، خيرٌ من أولئك المهلَكين، أم لكم براءةٌ من العذابِ في الكتب؟ ففي هذا التهديدُ لكفّارِ قريشٍ بمصيرِ من قبلهم؛ فاعلم أنّ سنّةَ الله واحدةٌ في المكذّبين، فلا تأمن العذابَ إن كذّبت، فالكفرُ سببُ الهلاكِ للجميع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مصيرِ المكذّبين، وإدراكُ أنّ سنّةَ الله واحدة."},"action":{"text":"تأمّل التهديدَ لكفّارِ قريش: أكفاركم، يا معشر قريش، خيرٌ وأقوى من أولئك المكذّبين المهلَكين (قومِ نوحٍ وعادٍ وثمودَ وقومِ لوطٍ وآلِ فرعون)، حتى تأمنوا العذاب؟ لستم بخيرٍ منهم؛ أم لكم براءةٌ وأمانٌ من العذابِ مكتوبٌ في الكتبِ السماوية؟ لا براءةَ لكم «أكفاركم خير من أولئكم أم لكم براءة في الزبر»؛ ففي هذا التهديدُ لكفّارِ قريشٍ بأنهم ليسوا خيرًا من المهلَكين قبلهم، ولا براءةَ لهم من العذاب؛ فمصيرهم كمصيرِ من قبلهم إن كذّبوا؛ فاعلم أنت أنّ سنّةَ الله واحدةٌ في المكذّبين في كلِّ زمان؛ فلن تجد لسنّةِ الله تبديلًا؛ أهم خيرٌ أم قومُ تبّعٍ والذين من قبلهم؛ فلا تأمن أنت العذابَ إن كذّبت أو كفرت؛ فالكفرُ والتكذيبُ سببُ الهلاكِ للجميع بلا استثناء؛ فمن اتّعظ بمصيرِ المكذّبين نجا، ومن اغترّ وكذّب هلك؛ فاجعل الحذرَ من مصيرِ المكذّبين وإدراكَ أنّ سنّةَ الله واحدةٌ دأبك."}},{"n":44,"reflection":{"text":"«أم يقولون نحن جميع منتصر»: أم يقول كفّارُ قريش: نحن جماعةٌ متناصرةٌ ننتصر على من عادانا؟ ففي هذا حكايةُ اغترارهم بكثرتهم؛ فاحذر الاغترارَ بالكثرةِ والقوّة، فالنصرُ من الله لا بالكثرة، فلا تتّكل على العددِ بل على الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالكثرة، والاعتمادُ على الله في النصر."},"action":{"text":"تأمّل اغترارَهم بكثرتهم: أم يقول كفّارُ قريش مغترّين بكثرتهم وقوّتهم: نحن جماعةٌ كثيرةٌ متناصرةٌ منتصرةٌ على من أرادنا بسوء، لا نُغلَب؟ «أم يقولون نحن جميع منتصر»؛ ففي هذا حكايةُ اغترارِ كفّارِ قريشٍ بكثرتهم وتناصرهم، وظنّهم أنهم لا يُغلَبون؛ فاغترّوا بالعددِ والقوّة؛ فاحذر أنت الاغترارَ بالكثرةِ والقوّةِ والعدد؛ فالنصرُ من الله وحده لا بالكثرة؛ وما النصرُ إلا من عند الله؛ كم من فئةٍ قليلةٍ غلبت فئةً كثيرةً بإذنِ الله؛ ويومَ حنينٍ إذ أعجبتكم كثرتكم فلم تُغنِ عنكم شيئًا؛ فلا تتّكل أنت على العددِ والقوّة، بل على الله؛ فمن اعتمد على الله نُصِر، ومن اغترّ بكثرته خُذِل؛ فاجعل عدمَ الاغترارِ بالكثرةِ والاعتمادَ على الله في النصرِ دأبك."}},{"n":45,"reflection":{"text":"«سيهزم الجمع ويولون الدبر»: سيُهزَم جمعُ الكفّارِ ويولّون منهزمين؛ ففي هذا وعدٌ بنصرِ المؤمنين وهزيمةِ الكافرين؛ فاثق بوعدِ الله بنصرِ الحقِّ وهزيمةِ الباطل، فالعاقبةُ للحقِّ وأهله، فلا تخف من جمعِ الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بوعدِ الله بنصرِ الحق، وعدمُ الخوفِ من جمعِ الباطل."},"action":{"text":"تأمّل وعدَ النصر: سيُهزَم جمعُ الكفّارِ وجماعتهم المغترّةُ بكثرتها، ويولّون الأدبارَ منهزمين (وقد تحقّق ذلك في بدر)؛ فلا تنفعهم كثرتهم «سيهزم الجمع ويولون الدبر»؛ ففي هذا وعدٌ من الله بنصرِ المؤمنين وهزيمةِ الكافرين، وقد تحقّق يومَ بدر؛ فهُزِم جمعهم رغمَ كثرتهم؛ فقال عمرُ: أيُّ جمعٍ يُهزَم؟ فلمّا كان يومُ بدرٍ رأى النبيَّ يثب في الدرعِ ويقول: سيُهزَم الجمعُ ويولّون الدبر؛ فاثق أنت بوعدِ الله بنصرِ الحقِّ وأهله وهزيمةِ الباطلِ وأهله؛ فالعاقبةُ للحقِّ وأهله؛ إنّا لننصر رسلنا والذين آمنوا؛ وكان حقًّا علينا نصرُ المؤمنين؛ فلا تخف أنت من جمعِ الباطلِ وكثرته؛ فمن وثق بوعدِ الله ثبت ونُصِر، ومن خاف جمعَ الباطلِ خُذِل؛ فاجعل الثقةَ بوعدِ الله بنصرِ الحقِّ وعدمَ الخوفِ من جمعِ الباطلِ دأبك."}},{"n":46,"reflection":{"text":"«بل الساعة موعدهم والساعة أدهى وأمر»: بل الساعةُ موعدُ عذابهم الأكبر، والساعةُ أعظمُ وأشدُّ مرارةً؛ ففي هذا بيانُ أنّ العذابَ الأكبرَ في الآخرة؛ فاستعدّ للساعةِ التي هي أدهى وأمرّ، فعذابُ الآخرةِ أشدّ، فاعمل لها قبل مجيئها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للساعة، وإدراكُ أنّ عذابَ الآخرةِ أشدّ."},"action":{"text":"تأمّل أنّ العذابَ الأكبرَ في الآخرة: بل الساعةُ (يومُ القيامة) هي موعدُ عذابِ الكفّارِ الأكبر، لا عذابُ الدنيا وحده؛ والساعةُ أدهى، أي أعظمُ داهيةً وأفظع، وأمرُّ، أي أشدُّ مرارةً وألمًا من عذابِ الدنيا «بل الساعة موعدهم والساعة أدهى وأمر»؛ ففي هذا بيانُ أنّ العذابَ الأكبرَ للكفّارِ في الآخرةِ يومَ الساعة، وأنه أعظمُ وأمرُّ من عذابِ الدنيا؛ فعذابُ الآخرةِ أشدُّ وأبقى؛ فاستعدّ أنت للساعةِ التي هي أدهى وأمرّ؛ ولعذابُ الآخرةِ أشقّ؛ وللعذابُ الأكبرُ أشدّ؛ فعذابُ الآخرةِ أشدُّ من عذابِ الدنيا وأبقى؛ فاعمل أنت للآخرةِ والساعةِ بالإيمانِ والعملِ الصالحِ قبل مجيئها؛ فمن استعدّ للساعةِ بالعملِ نجا، ومن غفل عنها خسر؛ فاجعل الاستعدادَ للساعةِ وإدراكَ أنّ عذابَ الآخرةِ أشدُّ دأبك."}},{"n":47,"reflection":{"text":"«إن المجرمين في ضلال وسعر»: إنّ المجرمين في ضلالٍ في الدنيا وعذابٍ (سعرٍ) في الآخرة؛ ففي هذا بيانُ حالِ المجرمين؛ فاحذر الإجرامَ الذي يورث الضلالَ والعذاب، فاجتنب الجرائمَ والمعاصي، فالإجرامُ سببُ الضلالِ والسعير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الإجرامِ والمعاصي، والحذرُ من الضلالِ والعذاب."},"action":{"text":"تأمّل حالَ المجرمين: إنّ المجرمين المكذّبين في ضلالٍ عن الحقِّ في الدنيا، وفي سُعُرٍ، أي عذابٍ وجنونٍ ونيرانٍ مستعرةٍ في الآخرة «إن المجرمين في ضلال وسعر»؛ ففي هذا بيانُ حالِ المجرمين: الضلالُ في الدنيا، والعذابُ (السعير) في الآخرة؛ فجزاءُ إجرامهم الضلالُ والعذاب؛ فاحذر أنت الإجرامَ والمعاصيَ التي تورث الضلالَ والعذاب؛ فالإجرامُ سببُ الضلالِ في الدنيا والسعيرِ في الآخرة؛ إنّ الذين أجرموا كانوا من الذين آمنوا يضحكون؛ وأمّا الذين فسقوا فمأواهم النار؛ فاجتنب أنت الجرائمَ والمعاصيَ والكبائر؛ فمن اجتنب الإجرامَ نجا من الضلالِ والعذاب، ومن أجرم ضلّ وعُذّب؛ فاجعل اجتنابَ الإجرامِ والمعاصي والحذرَ من الضلالِ والعذابِ دأبك."}},{"n":48,"reflection":{"text":"«يوم يسحبون في النار على وجوههم ذوقوا مس سقر»: يومَ يُجَرّون في النارِ على وجوههم، يُقال لهم: ذوقوا حرَّ جهنّم؛ ففي هذا بيانُ إهانةِ المجرمين في النار؛ فاحذر أن تُسحَب في النارِ على وجهك، فاعمل لتنجو منها، فإهانةُ المجرمين جزاءُ إجرامهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنجاةِ من النار، والحذرُ من الإهانةِ فيها."},"action":{"text":"تأمّل إهانةَ المجرمين: يومَ يُسحَب المجرمون ويُجَرّون في النارِ على وجوههم إهانةً وإذلالًا؛ يُقال لهم توبيخًا: ذوقوا مسَّ سقر، أي حرَّ جهنّمَ ولفحها ومسّها المؤلم «يوم يسحبون في النار على وجوههم ذوقوا مس سقر»؛ ففي هذا بيانُ إهانةِ المجرمين في النار، بسحبهم على وجوههم وتوبيخهم؛ فيُسحَبون على وجوههم مهانين؛ فاحذر أنت أن تُسحَب في النارِ على وجهك مهانًا؛ فاعمل عملًا صالحًا لتنجو منها؛ فيُسحَبون في الحميمِ ثم في النارِ يُسجَرون؛ يومَ يُدَعّون إلى نارِ جهنّمَ دعًّا؛ فإهانةُ المجرمين وسحبهم على وجوههم جزاءُ إجرامهم وتكذيبهم؛ فمن عمل للنجاةِ من النارِ نجا وأُكرِم، ومن أجرم أُهين وسُحِب فيها؛ فاجعل العملَ للنجاةِ من النارِ دأبك."}},{"n":49,"reflection":{"text":"«إنا كل شيء خلقناه بقدر»: إنا خلقنا كلَّ شيءٍ بقدرٍ وتقديرٍ سابق؛ ففي هذا تقريرُ عمومِ القدر؛ فآمن بأنّ كلَّ شيءٍ بقدرِ الله وتقديره، فسلّم لقدرِ الله وارضَ به، فالإيمانُ بالقدرِ من أركانِ الإيمان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالقدرِ والتسليمُ له، والرضا بتقديرِ الله."},"action":{"text":"تأمّل تقريرَ عمومِ القدر: إنا خلقنا كلَّ شيءٍ في الكونِ بقدرٍ، أي بتقديرٍ سابقٍ وحكمةٍ وعلمٍ، كتبناه في اللوحِ المحفوظِ قبل خلقه؛ فكلُّ شيءٍ بقضاءٍ وقدر «إنا كل شيء خلقناه بقدر»؛ ففي هذا تقريرُ أنّ كلَّ شيءٍ في الكونِ مخلوقٌ بقدرِ الله وتقديره وحكمته؛ فلا يقع شيءٌ إلا بقدرٍ سابق؛ فآمن أنت بأنّ كلَّ شيءٍ، خيرَه وشرَّه، نفعَه وضرَّه، بقدرِ الله وتقديره وعلمه؛ ما أصاب من مصيبةٍ في الأرضِ ولا في أنفسكم إلا في كتاب؛ وخلق كلَّ شيءٍ فقدّره تقديرًا؛ وكان أمرُ الله قدرًا مقدورًا؛ (وهذه الآيةُ أصلٌ في إثباتِ القدر)؛ فسلّم لقدرِ الله وارضَ به فيما يصيبك؛ فالإيمانُ بالقدرِ خيرِه وشرِّه من أركانِ الإيمان؛ فمن آمن بالقدرِ وسلّم له اطمأنّ، ومن أنكره أو اعترض عليه تعب؛ فاجعل الإيمانَ بالقدرِ والتسليمَ له والرضا بتقديرِ الله دأبك."}},{"n":50,"reflection":{"text":"«وما أمرنا إلا واحدة كلمح بالبصر»، وما أمرنا (في خلقِ الأشياءِ والبعث) إلا كلمةٌ واحدةٌ كطرفةِ العين؛ ففي هذا بيانُ سرعةِ نفوذِ أمرِ الله وقدرته؛ فاعلم أنّ الله يفعل ما يشاء بأسرعَ من لمحِ البصر، فأيقن بقدرته على كلِّ شيءٍ وعلى البعث، فقدرةُ الله لا يعجزها شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بقدرةِ الله وسرعةِ نفوذِ أمره، وإدراكُ قدرته على البعث."},"action":{"text":"تأمّل سرعةَ نفوذِ أمرِ الله: وما أمرنا في خلقِ الأشياءِ وإيجادها وفي البعثِ إلا مرّةٌ واحدةٌ، بكلمةِ «كن» فيكون، بلا معالجةٍ ولا تكرار؛ كلمحٍ بالبصر، أي كطرفةِ العينِ في السرعة، بل أسرع «وما أمرنا إلا واحدة كلمح بالبصر»؛ ففي هذا بيانُ سرعةِ نفوذِ أمرِ الله وقدرته، حيث يوجد الأشياءَ بكلمةٍ واحدةٍ أسرعَ من لمحِ البصر؛ فأمره نافذٌ سريع؛ فاعلم أنت أنّ الله يفعل ما يشاء بكلمةٍ واحدةٍ أسرعَ من لمحِ البصر؛ إنما أمره إذا أراد شيئًا أن يقول له كن فيكون؛ وما أمرُ الساعةِ إلا كلمحِ البصرِ أو هو أقرب؛ فأيقن أنت بقدرةِ الله على كلِّ شيء، وعلى البعثِ والإعادةِ في لمحة؛ وما خلقكم ولا بعثكم إلا كنفسٍ واحدة؛ فقدرةُ الله لا يعجزها شيء، وأمره نافذٌ سريع؛ فمن أيقن بقدرةِ الله آمن بالبعث، ومن جهلها شكّ فيه؛ فاجعل اليقينَ بقدرةِ الله وسرعةِ نفوذِ أمره دأبك."}}]},{"title":"إهلاكُ الأشباه، وإحصاءُ الأعمال، ونعيمُ المتّقين","range":[51,55],"theme":"التذكيرُ بإهلاكِ أشياعِ الكفّارِ فهل من مدكر، وأنّ كلَّ شيءٍ فعلوه في الزبرِ وكلَّ صغيرٍ وكبيرٍ مستطر، وختامُ السورةِ بأنّ المتّقين في جنّاتٍ ونهرٍ في مقعدِ صدقٍ عند مليكٍ مقتدر","verses":[{"n":51,"reflection":{"text":"«ولقد أهلكنا أشياعكم فهل من مدكر»، ولقد أهلكنا أشباهكم في الكفرِ من الأممِ السابقة، فهل من متّعظ؟ ففي هذا التذكيرُ بإهلاكِ الأشباهِ والحثُّ على الاتّعاظ؛ فاتّعظ بإهلاكِ من أشبهوك في الكفرِ إن كفرت، فسنّةُ الله في المكذّبين واحدة، فكن من المدّكرين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بإهلاكِ الأشباه، وكونُ العبدِ من المدّكرين."},"action":{"text":"تأمّل التذكيرَ بإهلاكِ الأشباه: ولقد أهلكنا أشياعكم، أي أشباهكم ونظراءكم في الكفرِ والتكذيبِ من الأممِ السابقة؛ فهل من مدّكرٍ متّعظٍ يعتبر بذلك فيؤمن؟ «ولقد أهلكنا أشياعكم فهل من مدكر»؛ ففي هذا التذكيرُ بإهلاكِ الأممِ التي أشبهت المشركين في الكفر، والحثُّ على الاتّعاظ؛ فأهلك الله أشباههم فليعتبروا؛ فاتّعظ أنت بإهلاكِ من أشبهوك في الكفرِ والتكذيبِ إن سلكت سبيلهم؛ فسنّةُ الله في المكذّبين واحدةٌ لا تتبدّل؛ وكم أهلكنا من قبلهم من قرن؛ فهل تحسّ منهم من أحدٍ أو تسمع لهم ركزًا؛ فكن أنت من المدّكرين المتّعظين بإهلاكِ الأمم؛ فمن اتّعظ بإهلاكِ الأشباهِ نجا، ومن أعرض عنه هلك مثلهم؛ فاجعل الاتّعاظَ بإهلاكِ الأشباهِ وكونَك من المدّكرين دأبك."}},{"n":52,"reflection":{"text":"«وكل شيء فعلوه في الزبر»، وكلُّ شيءٍ فعله العبادُ مكتوبٌ في الكتب (صحفِ الأعمال)؛ ففي هذا بيانُ إحصاءِ الأعمال؛ فاعلم أنّ كلَّ عملك مكتوبٌ محفوظ، فراقب الله في عملك، فما من عملٍ إلا وهو مسطورٌ عليك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في العمل، وإدراكُ أنّ كلَّ عملٍ مكتوب."},"action":{"text":"تأمّل إحصاءَ الأعمال: وكلُّ شيءٍ فعله العبادُ من خيرٍ أو شرٍّ، صغيرٍ أو كبير، مكتوبٌ ومثبَتٌ في الزُّبُر، أي في الكتبِ وصحفِ الأعمالِ التي تكتبها الملائكة، أو في اللوحِ المحفوظ «وكل شيء فعلوه في الزبر»؛ ففي هذا بيانُ أنّ كلَّ ما فعله العبادُ مكتوبٌ محفوظٌ في الكتب؛ فلا يضيع من أعمالهم شيء؛ فاعلم أنت أنّ كلَّ عملك، قليلَه وكثيره، مكتوبٌ محفوظٌ عليك؛ وإنّ عليكم لحافظين، كرامًا كاتبين، يعلمون ما تفعلون؛ ووُضِع الكتابُ فترى المجرمين مشفقين ممّا فيه؛ فراقب الله في كلِّ عملٍ وقولٍ وحركة؛ فما من عملٍ إلا وهو مسطورٌ عليك في صحيفتك؛ فمن راقب الله في عمله أحسن، ومن غفل أساء؛ فاجعل مراقبةَ الله في العملِ وإدراكَ أنّ كلَّ عملٍ مكتوبٌ دأبك."}},{"n":53,"reflection":{"text":"«وكل صغير وكبير مستطر»، وكلُّ صغيرٍ وكبيرٍ من الأعمالِ مكتوبٌ مسطور؛ ففي هذا تأكيدُ إحصاءِ الأعمالِ كلِّها؛ فاحذر الصغائرَ كما تحذر الكبائر، فكلُّها مكتوبةٌ محاسبٌ عليها، فراقب الله في صغيرِ عملك وكبيره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الصغائرِ والكبائر، ومراقبةُ الله في كلِّ عمل."},"action":{"text":"تأمّل تأكيدَ إحصاءِ الأعمال: وكلُّ صغيرٍ وكبيرٍ من أعمالِ العبادِ وأقوالهم مستطرٌ، أي مكتوبٌ مسطورٌ في اللوحِ المحفوظِ وصحفِ الأعمال، لا يُغادَر منه شيء «وكل صغير وكبير مستطر»؛ ففي هذا تأكيدُ أنّ كلَّ الأعمالِ، صغيرها وكبيرها، مكتوبةٌ محفوظة؛ فلا يفوت منها شيء؛ فاحذر أنت الصغائرَ كما تحذر الكبائر؛ فكلُّها مكتوبةٌ محاسبٌ عليها؛ ووُضِع الكتابُ فترى المجرمين مشفقين ممّا فيه ويقولون يا ويلتنا ما لهذا الكتابِ لا يغادر صغيرةً ولا كبيرةً إلا أحصاها؛ ونكتب ما قدّموا وآثارهم وكلَّ شيءٍ أحصيناه في إمامٍ مبين؛ فراقب الله في صغيرِ عملك وكبيره؛ فمن حذر الصغائرَ والكبائرَ وراقب الله نجا، ومن تهاون بها هلك؛ فاجعل الحذرَ من الصغائرِ والكبائرِ ومراقبةَ الله في كلِّ عملٍ دأبك."}},{"n":54,"reflection":{"text":"«إن المتقين في جنات ونهر»: إنّ المتّقين في بساتينَ وأنهارٍ جارية؛ ففي هذا بيانُ جزاءِ المتّقين؛ فاطلب جنّاتِ المتّقين وأنهارها بالتقوى، فالجنّةُ جزاءُ التقوى، فاعمل بالتقوى لتنالها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ جنّاتِ المتّقين بالتقوى، والعملُ لها."},"action":{"text":"تأمّل جزاءَ المتّقين: إنّ المتّقين الذين اتّقوا الله بفعلِ أوامره واجتنابِ نواهيه، في الآخرةِ في جنّاتٍ وبساتينَ عظيمة، ونهرٍ، أي أنهارٍ جاريةٍ من الماءِ واللبنِ والخمرِ والعسل؛ فبعد ذكرِ المجرمين وعذابهم، ذكر المتّقين ونعيمهم مقابلةً «إن المتقين في جنات ونهر»؛ ففي هذا بيانُ جزاءِ المتّقين: الجنّاتُ والأنهار؛ فجزاؤهم بتقواهم الجنّةُ ونعيمها؛ فاطلب أنت جنّاتِ المتّقين وأنهارها بالتقوى؛ فالجنّةُ جزاءُ أهلِ التقوى؛ إنّ المتّقين في جنّاتٍ وعيون؛ مثلُ الجنّةِ التي وُعِد المتّقون فيها أنهار؛ فاعمل بالتقوى، فعلِ المأموراتِ وتركِ المحظورات، لتنال الجنّة؛ فمن اتّقى نال الجنّةَ وأنهارها، ومن فرّط حُرِمها؛ فاجعل التقوى سبيلك لنيلِ جنّاتِ المتّقين."}},{"n":55,"reflection":{"text":"«في مقعد صدق عند مليك مقتدر»: في مجلسِ حقٍّ وصدقٍ لا لغوَ فيه، عند مالكٍ قادرٍ عظيم؛ ففي هذا بيانُ أعظمِ نعيمِ الجنّة: القربُ من الله؛ فاطلب هذا المقامَ العظيمَ (القربَ من الله) بالتقوى، فأعظمُ نعيمِ الجنّةِ رضا الله وقربه، فاعمل لتنال قربه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ القربِ من الله بالتقوى، وإدراكُ أنه أعظمُ النعيم."},"action":{"text":"تأمّل أعظمَ نعيمِ الجنّة: المتّقون في الجنّةِ في مقعدِ صدقٍ، أي مجلسِ حقٍّ ورضًا لا لغوَ فيه ولا تأثيم، ثابتٍ دائم؛ عند مليكٍ، أي مالكٍ عظيمٍ لكلِّ شيء، مقتدرٍ لا يعجزه شيء، وهو الله؛ فهم في جوارِ الله وقربه ورضاه «في مقعد صدق عند مليك مقتدر»؛ ففي هذا بيانُ أعظمِ نعيمِ الجنّة: القربُ من الله الملِكِ المقتدرِ ورضاه؛ فبعد ذكرِ الجنّاتِ والأنهار، ذكر أعظمَ نعيمها: القربَ من الله؛ فأعظمُ نعيمِ أهلِ الجنّةِ النظرُ إلى وجهِ الله ورضاه وقربه؛ فاطلب أنت هذا المقامَ العظيمَ، القربَ من الله ورضاه، بالتقوى والعملِ الصالح؛ ورضوانٌ من الله أكبر؛ للذين أحسنوا الحسنى وزيادة (والزيادةُ النظرُ إلى وجهِ الله)؛ وجوهٌ يومئذٍ ناضرة، إلى ربّها ناظرة؛ فأعظمُ نعيمِ الجنّةِ رضا الله وقربه والنظرُ إليه؛ فاعمل بالتقوى لتنال قربَ الله ورضاه؛ فمن اتّقى نال القربَ والرضا، ومن فرّط حُرِمهما؛ فاجعل طلبَ القربِ من الله بالتقوى وإدراكَ أنه أعظمُ النعيمِ دأبك."}}]}],"coverage":{"covered":55,"total":55}};
